      "content": "// ========= Copyright 2026 @ Strukto.AI All Rights Reserved. =========\n// Licensed under the Apache License, Version 2.0 (the \"License\");\n// you may not use this file except in compliance with the License.\n// You may obtain a copy of the License at\n//\n//     http://www.apache.org/licenses/LICENSE-2.0\n//\n// Unless required by applicable law or agreed to in writing, software\n// distributed under the License is distributed on an \"AS IS\" BASIS,\n// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n// See the License for the specific language governing permissions and\n// limitations under the License.\n// ========= Copyright 2026 @ Strukto.AI All Rights Reserved. =========\n\nimport type { FileCacheMixin } from '../../cache/file/mixin.ts'\nimport {\n  type IndexConfig,\n  normalizeIndexConfig,\n  type RedisIndexConfig,\n} from '../../cache/index/config.ts'\nimport { ListingCheckStore } from '../../cache/index/ram.ts'\nimport { KeyLock } from '../../cache/lock.ts'\nimport { cliSpecFor } from '../../commands/cli/specs.ts'\nimport type { CLI } from '../../commands/cli/types.ts'\nimport {\n  type Caller,\n  currentCaller,\n  getAdmission,\n  getCurrentSessionFor,\n  getCurrentSessionUnlessForeign,\n  runAsProgram,\n  runExplaining,\n  runWithCaller,\n  runAsProcess,\n  runWithRefusalSink,\n  runWithSession,\n  sessionAccess,\n  sessionCaller,\n  sessionVisibility,\n} from '../../context/session_context.ts'\nimport { enoent } from '../../errors/fs.ts'\nimport type { EventRuntime } from '../../events/base.ts'\nimport { newLineId } from '../../execution/context.ts'\nimport { LineTable } from '../../execution/line/table.ts'\nimport type { Line, LineState } from '../../execution/line/types.ts'\nimport { IOConfig } from '../../io/config.ts'\nimport { MAX_BODY_BYTES, MAX_MEMORY, MemoryBudget } from '../../io/memory.ts'\nimport { networkRule, type NetworkSetting, runWithNetwork, sameNetwork } from '../../io/network.ts'\nimport { HISTFILESIZE } from '../../core/history/constants.ts'\nimport { EVENT_COMMAND, EVENT_RESULT, EVENT_VFS } from '../../observe/log_entry.ts'\nimport { Observer } from '../../observe/observer.ts'\nimport type { OpRecord } from '../../observe/record.ts'\nimport { checkCommandLimits } from '../../policy/builtin/output_cap.ts'\nimport { PermissionsPolicy } from '../../policy/builtin/permissions.ts'\nimport { RoutePolicy } from '../../policy/builtin/route.ts'\nimport { Decisions } from '../../policy/decisions.ts'\nimport { PolicyError } from '../../policy/errors.ts'\nimport type { Policies } from '../../policy/index.ts'\nimport {\n  parseProfileMounts,\n  parseProfilePolicy,\n  type CompiledProfile,\n  type SessionProfile,\n} from '../../policy/profile.ts'\nimport { ScriptPolicy } from '../../policy/script.ts'\nimport { DryRun, Outcome, policyCaller, type ShellExplanation } from '../../policy/types.ts'\nimport { ChildProcess } from '../../execution/process/child.ts'\nimport { statedProcesses, type ProcessPermissions } from '../../execution/process/config.ts'\nimport { ProcessInput, ProcessOutput } from '../../execution/process/stdio.ts'\nimport { ProcessTable } from '../../execution/process/table.ts'\nimport type { Process, ProcessState, SpawnRequest } from '../../execution/process/types.ts'\nimport { LINE_STOP_SIGNAL, LOCAL_MACHINE } from '../../execution/constants.ts'\nimport type { ProcessId } from '../../execution/types.ts'\nimport { type JobId, type LineId, type MachineId, type MachinePid } from '../../execution/types.ts'\nimport type { SessionProcesses } from '../../execution/process/session.ts'\nimport { DiffPool } from '../../rs/diff_pool.ts'\nimport type { Runtime, RuntimeEntry } from '../../runtime/base.ts'\nimport {\n  captureBinding,\n  restrictedMountsFor,\n  type RuntimeContext,\n  WorkspaceBinding,\n} from '../../runtime/binding.ts'\nimport { PrefixResolver } from '../../runtime/resolver.ts'\nimport { MachineTable } from '../../execution/machine/table.ts'\nimport type { MachineProcess } from '../../execution/machine/types.ts'\nimport type { Machine } from '../../execution/machine/types.ts'\nimport { wholeLineRuntime } from '../../runtime/table.ts'\nimport type { DispatchFn } from '../../runtime/types.ts'\nimport { SecretSource } from '../../secrets/config.ts'\nimport { SecretsError } from '../../secrets/errors.ts'\nimport { sourceFor } from '../../secrets/registry.ts'\nimport { resolveSources } from '../../secrets/sources.ts'\nimport type { ResolvedSource } from '../../secrets/types.ts'\nimport { Terminal } from '../../shell/console/terminal.ts'\nimport { BIN_PREFIX } from '../../shell/constants.ts'\nimport { compareCodePoints } from '../../utils/sort.ts'\nimport { HANGUP_EXIT_CODE } from '../../execution/job/constants.ts'\nimport { type Job, type JobState, JobTable } from '../../execution/job/index.ts'\nimport { shellJoin } from '../../shell/join.ts'\nimport { literalTree } from '../../shell/literal.ts'\nimport { ParseScope } from '../../shell/parse/scope.ts'\nimport type { TSNodeLike } from '../../shell/types.ts'\nimport { makeVar, VarAttr } from '../../shell/variable.ts'\nimport type { FileEvent, JsonObject, Visibility } from '../../types.ts'\nimport {\n  DEFAULT_READ_SPEC,\n  DriftPolicy,\n  MountMode,\n  parseMountMode,\n  PathSpec,\n  type ReadSpec,\n  underCeiling,\n  WritePolicy,\n} from '../../types.ts'\nimport { abortable } from '../../utils/abort.ts'\nimport { asyncContextIsolatesTasks } from '../../utils/async_context.ts'\nimport {\n  type Clock,\n  parseSystemTime,\n  ShiftedClock,\n  SystemClock,\n  systemNow,\n} from '../../utils/clock.ts'\nimport { pathVisible } from '../../utils/hidden.ts'\nimport { checkName, type IdSource, SystemIdSource } from '../../utils/ids.ts'\nimport { parseLimit } from '../../utils/size.ts'\nimport { normDir, rstripSlash } from '../../utils/slash.ts'\nimport type { BaseVFS } from '../../vfs/base.ts'\nimport { BinViewVFS } from '../../vfs/bin/bin.ts'\nimport { HISTORY_PREFIX, HistoryViewVFS } from '../../vfs/history/history.ts'\nimport { RAMVFS } from '../../vfs/ram/ram.ts'\nimport type { S3Config } from '../../vfs/s3/config.ts'\nimport type { OpKwargs, SessionView } from '../../view/types.ts'\nimport { newStatusWriter, runWithLineAbort } from '../abort.ts'\nimport type { CLIInstall } from '../cli/types.ts'\nimport { Dispatcher } from '../dispatcher/index.ts'\nimport { Documents } from '../documentation/documents.ts'\nimport { LineHandle } from '../../execution/line/handle.ts'\nimport { expandingAliases } from '../executor/builtins/alias/alias.ts'\nimport { recordStatus } from '../executor/statement.ts'\nimport { classifyBarePath } from '../expand/classify/path.ts'\nimport { resolveGlobs } from '../expand/globs.ts'\nimport { Files, withCaller, WorkspaceFiles } from '../files.ts'\nimport { lookup, program, programNote, programs } from '../lookup/lookup.ts'\nimport { Consumer } from '../lookup/types.ts'\nimport { WritePolicyError } from '../mount/errors.ts'\nimport type { MountEntry } from '../mount/mount.ts'\nimport { Namespace } from '../mount/namespace/namespace.ts'\nimport { checkReadCapability } from '../mount/read_policy.ts'\nimport { MountRegistry } from '../mount/registry.ts'\nimport { Mount } from '../mount/spec.ts'\nimport { checkWriteCapability, coerceWritePolicy } from '../mount/write_policy.ts'\nimport {\n  explainedLine,\n  explainLine,\n  holds,\n  lineJudgments,\n  offLineRefusal,\n} from '../node/explain.ts'\nimport { decodeText } from '../../shell/bytes.ts'\nimport { DEFAULT_PROFILE, MAX_ENV } from '../session/constants.ts'\nimport { checkEnvFits } from '../session/budget.ts'\nimport { SessionManager } from '../session/manager.ts'\nimport { compileProfile, resolveProfile, withInline } from '../session/resolve.ts'\nimport { type SessionState, varsFromEntries, varsFromEnv } from '../session/session.ts'\nimport { envSnapshot, sessionView } from '../session/state.ts'\nimport { checkCliVerbs } from '../session/validate.ts'\nimport { ShellExecution } from '../shell_execution.ts'\nimport { readSnapshot, snapshot as writeSnapshot } from '../snapshot/api.ts'\nimport { indexConfigDump } from '../snapshot/config.ts'\nimport { DriftQueue, installFingerprints } from '../snapshot/drift.ts'\nimport { makeStagingDir, removeDir } from '../snapshot/fs.ts'\nimport {\n  applyStateDict,\n  buildMountArgs,\n  type CLIOverrides,\n  reusableClis,\n  reusableMounts,\n  toStateDict,\n  withRebuiltMounts,\n} from '../snapshot/state.ts'\nimport type { MountSnapshot, WorkspaceStateDict } from '../snapshot/types.ts'\nimport { QUIESCE_SECONDS } from '../snapshot/utils.ts'\nimport type { WorkspaceStateStore } from '../store/base.ts'\nimport { FileVersionTracker } from '../tools/file_version.ts'\nimport { MirageToolOperations } from '../tools/tool_operations.ts'\nimport { resolveControlStores } from './build.ts'\nimport { buildFileCache } from './cache.ts'\nimport { EventManager } from './events.ts'\nimport { type ExecuteEnv, executeLine } from './execute.ts'\nimport { Explainer } from './explainer.ts'\nimport { placementRefused } from './failure.ts'\nimport { fillEnv } from './fill.ts'\nimport { closeWorkspace } from './lifecycle.ts'\nimport { WorkspaceMeta } from './meta.ts'\nimport { normalizeMounts, prepareAddedMount, unmountPrefix } from './mounts.ts'\nimport { Router } from './routing.ts'\nimport { Runtimes } from './runtimes.ts'\nimport type {\n  ExecuteOptions,\n  ExecuteResult,\n  MountSpec,\n  SessionExecuteOptions,\n  WorkspaceOptions,\n} from './types.ts'\nimport { forkForCall } from './utils.ts'\n\nexport { ExecuteResult } from './types.ts'\nexport type { ExecuteOptions, MountSpec, SessionExecuteOptions, WorkspaceOptions } from './types.ts'\n\n/** A workspace's secret source declarations and its seed variables. Mirrors Python's _declared_sources. */\nfunction declaredSources(options: WorkspaceOptions) {\n  // The env block, translated once: a literal entry becomes an\n  // exported var, a managed one becomes a pointer the fill step\n  // resolves at command time. Each managed entry's source is\n  // resolved now, so a typo'd name (or a source nothing registered)\n  // fails at construction, naming the known sources, rather than at\n  // the first fetch.\n  // The source table, kept as declarations: building one reads its\n  // bootstrap pointers, which is I/O, and this constructor is sync.\n  // `secretSources` builds them once, before the first fetch.\n  // Checked here, so every caller-supplied route is covered at once:\n  // an array arrives from an untyped REST override, and\n  // `Object.entries` on one yields nothing, so the declarations\n  // would silently vanish and every restored pointer would read as\n  // an unknown source.\n  // Read as `unknown` on purpose: the declared type says mapping,\n  // and the value comes from an untyped REST override that can say\n  // otherwise, which is exactly the case being caught.\n  const declared: unknown = options.secrets\n  if (\n    declared !== undefined &&\n    (typeof declared !== 'object' || declared === null || Array.isArray(declared))\n  ) {\n    throw new SecretsError('config `secrets` must be a mapping')\n  }\n  const sources: Record<string, SecretSource> = Object.fromEntries(\n    Object.entries(options.secrets ?? {}).map(([name, block]) => [name, SecretSource.parse(block)]),\n  )\n  for (const block of Object.values(sources)) sourceFor(block.source)\n  const seedVars = options.env !== undefined ? varsFromEntries(options.env) : undefined\n  for (const seeded of Object.values(seedVars ?? {})) {\n    if (seeded.managed !== undefined && !Object.hasOwn(sources, seeded.managed.source)) {\n      sourceFor(seeded.managed.source)\n    }\n  }\n  return [sources, seedVars] as const\n}\n\nexport class Workspace {\n  readonly io: IOConfig\n  private readonly runtimeBinding: WorkspaceBinding\n  readonly registry: MountRegistry\n  private readonly networkSetting: NetworkSetting\n  private readonly systemTimeSetting: string | null\n  readonly sessionManager: SessionManager\n  private readonly wsId: string\n  private readonly stateStoreInternal: WorkspaceStateStore\n  private readonly ownsStateStore: boolean\n  private readonly sharedMounts = new Set<BaseVFS>()\n  private readonly meta: WorkspaceMeta\n  private readonly indexConfig: IndexConfig | undefined\n  private readonly readDefault: ReadSpec\n  /** The write policy a mount added without one takes. */\n  readonly writeDefault: WritePolicy\n  readonly processTable: ProcessTable\n  readonly jobTable: JobTable\n  readonly lineTable: LineTable\n  readonly cache: FileCacheMixin & BaseVFS\n  /** The clock this workspace reads time and waits on; a rebuild that shares its mounts runs on it too. */\n  readonly clock: Clock\n  private readonly ids: IdSource\n  readonly namespace: Namespace\n  private readonly dispatcher: Dispatcher\n  readonly observer: Observer\n  readonly vfs: WorkspaceFiles\n  private readonly toolTables = new Map<string | null, MirageToolOperations>()\n  private readonly reads = new Map<string, FileVersionTracker>()\n  private readonly diffPool = new DiffPool()\n  private readonly shellExecutions = new Set<ShellExecution>()\n  private closed = false\n  readonly documents: Documents\n  private readonly lineLock = new KeyLock()\n  private readonly lineStops = new Map<\n    AbortController,\n    { sessionId: string | undefined; ended: Promise<void> }\n  >()\n  private admitting: Promise<void> = Promise.resolve()\n  private captures: Promise<void> = Promise.resolve()\n  private capturing = false\n  private readonly admitted = new Set<AbortController>()\n  private writes = 0\n  private writesIdle: Promise<void> = Promise.resolve()\n  private settleWrites: () => void = () => undefined\n  private readonly closers: (() => Promise<void>)[] = []\n  private closing: Promise<void> | null = null\n  private metaWrite: Promise<void> | null = null\n  private stateDropped = false\n  // The stores this workspace's state lives in, whether the state store\n  // built them or the caller passed one in directly: delete clears these,\n  // not only what the state store would hand out.\n  private readonly planes: { clear(): Promise<void> }[]\n\n  /**\n   * Whether no new work should be accepted.\n   *\n   * True from the moment `close()` is called, not from the moment teardown\n   * finishes. The two differ because `closed` is now set at the end so a\n   * runtime can still replay its journal, and that window would otherwise let\n   * a caller start a job after `killAll`, or add a mount after the close list\n   * was taken. Internal dispatch and recursive execution stay open until\n   * teardown finishes; their public entry points do not. A method keeps TypeScript\n   * from treating a pre-await check as proof that the state is still open.\n   */\n  private isShuttingDown(): boolean {\n    return this.closing !== null || this.closed\n  }\n  private readonly eventManager: EventManager\n  private readonly runtimeWorld: Runtimes\n  /** The machines its programs run on, by name. */\n  readonly machineTable: MachineTable\n  // Named for what it holds: the source declarations, never a secret.\n  private readonly declaredSecretSources: Readonly<Record<string, SecretSource>>\n  private keptView: { session: SessionState; policies: Policies; view: SessionView } | null = null\n  private secretSourcesBuilt: Readonly<Record<string, ResolvedSource>> | null = null\n  private readonly policyFunctions: Readonly<Record<string, (...args: never[]) => unknown>>\n  private secretSourcesPending: Promise<Record<string, ResolvedSource>> | null = null\n  private readonly router: Router\n  private readonly scriptPolicy: ScriptPolicy\n  // No prototype, so every name is an own entry: `__proto__` is stored\n  // rather than reparenting the table, and `toString` resolves to nothing.\n  private readonly profilesInternal = Object.create(null) as Record<string, SessionProfile>\n  /** The workspace's `processes` block as stated, which each profile's overrides. */\n  readonly workspaceProcesses: Partial<ProcessPermissions> | null\n  /** The profile table's default. */\n  readonly defaultProfileName: string | null\n  // True when `/` is an anchor the workspace added or a restore mounted (see syntheticRoot).\n  // The anchor is internal and is not forwarded into the Pyodide filesystem.\n  private syntheticRootAnchor = false\n  // Drift check state populated by Workspace.load. Empty during normal\n  // runs; drained on the first dispatch/execute after load.\n  protected readonly drift = new DriftQueue()\n\n  // FUSE lives entirely in the node Workspace (FUSE needs the OS; the browser\n  // can't mount), so the core Workspace carries no FUSE state.\n\n  constructor(mounts: Record<string, MountSpec>, options: WorkspaceOptions = {}) {\n    if ('python' in options) {\n      throw new Error(\n        \"the 'python' workspace option was removed: configure the engine on its runtimes entry, \" +\n          'e.g. new PyodideRuntime({ config: { denyPackages } })',\n      )\n    }\n    // The workspace-level default a mount overrides, as `mode` is.\n    this.io = new IOConfig(options.io)\n    this.readDefault = options.read ?? DEFAULT_READ_SPEC\n    this.writeDefault = coerceWritePolicy(options.write)\n    const index = options.index === undefined ? undefined : normalizeIndexConfig(options.index)\n    // Before the mounts: the write verdict asks whether the cache keeps anything.\n    this.clock = options.clock ?? new SystemClock()\n    this.ids = options.ids ?? new SystemIdSource(this.clock)\n    // Minted before any mount, so a seeded source hands out the same draws in\n    // the same order on both hosts.\n    this.wsId = options.workspaceId ?? this.ids.uuid7()\n    const sessionId = options.sessionId ?? this.ids.uuid7()\n    // A line binds the system clock only once its process has started.\n    this.processTable = new ProcessTable(\n      this.wsId,\n      this.hostMachine(),\n      runAsProcess,\n      () => {\n        this.jobTable.processesChanged()\n      },\n      () => this.registry.systemClock?.now() ?? systemNow(),\n      (record) => {\n        this.observer.traceProcess(record)\n      },\n      (record) => {\n        this.jobTable.store.note(record)\n      },\n    )\n    this.cache = buildFileCache(options.cache, options.cacheLimit, this.clock, this.wsId)\n    const normalized = normalizeMounts(mounts, this.readDefault, index, {\n      mode: options.mode ?? MountMode.READ,\n      write: this.writeDefault,\n      caching: this.cache.cacheLimit > 0,\n    })\n    this.indexConfig = index\n    this.registry = new MountRegistry(\n      normalized.bare,\n      options.mode ?? MountMode.READ,\n      normalized.modes,\n      this.readDefault,\n      normalized.read,\n      {\n        ...(index !== undefined ? { index } : {}),\n        refs: normalized.refs,\n        indexes: normalized.indexes,\n        defaultWrite: this.writeDefault,\n        writes: normalized.write,\n        workspaceId: this.wsId,\n      },\n      this.io,\n      this.clock,\n      this.ids,\n    )\n    this.registry.diff = this.diffPool\n    this.registry.sessionProcesses = (session) => this.sessionProcesses(session)\n    this.registry.fillEnv = (session, names) => this.fillTreeEnv(session, names)\n    const stores = resolveControlStores(this.wsId, options)\n    this.jobTable = new JobTable(\n      stores.execution,\n      this.processTable,\n      null,\n      this.clock,\n      options.daemonId ?? null,\n    )\n    this.jobTable.ended = (record) => {\n      this.traceJob(record)\n    }\n    this.jobTable.taken = () => this.endLost()\n    this.lineTable = new LineTable(this.clock, (record) => {\n      this.jobTable.store.note(record)\n    })\n    this.ownsStateStore = stores.owned\n    this.stateStoreInternal = stores.stateStore\n    const [sources, seedVars] = declaredSources(options)\n    this.declaredSecretSources = sources\n    this.sessionManager = new SessionManager(\n      sessionId