pSlash(prefix) || '/'))\n  }\n\n  /** The ordered runtime world, first capturer first. */\n  runtimes(): readonly Runtime[] {\n    return this.runtimeWorld.entries\n  }\n\n  /**\n   * Stop a host program a lapsed workspace left on this host, answering\n   * whether it is stopped or gone. A host whose processes this package\n   * cannot reach (a browser) reaches none; Node's workspace does.\n   */\n  protected stopHostRun(\n    _machinePid: MachinePid,\n    _seenAt: number | null,\n    _signum: number,\n  ): Promise<boolean> {\n    return Promise.resolve(false)\n  }\n\n  /**\n   * Every process of the host programs' process groups, each tagged as the\n   * Mirage process whose program leads it. A host whose processes this\n   * package cannot see (a browser) shows none; Node's workspace does.\n   */\n  protected scanHost(\n    _groups: ReadonlyMap<number, readonly [string, number]>,\n  ): Promise<MachineProcess[]> {\n    return Promise.resolve([])\n  }\n\n  /**\n   * Send a signal to a host process as `kill` sent it, answering whether it\n   * ran. A host whose processes this package cannot reach (a browser)\n   * reaches none; Node's workspace does.\n   */\n  protected signalHost(_target: MachinePid, _signum: number): Promise<boolean> {\n    return Promise.resolve(false)\n  }\n\n  /**\n   * The machine this workspace runs on, where its builtins and the programs\n   * it runs here run. Core cannot name its host; Node's and the browser's\n   * workspaces do.\n   */\n  protected hostMachine(): MachineId {\n    return LOCAL_MACHINE\n  }\n\n  /** Add a runtime entry to the workspace's ordered set; `Runtimes.add` places it. */\n  addRuntime(runtime: RuntimeEntry): Runtime {\n    if (this.isShuttingDown()) throw new Error('Workspace is closed')\n    return this.runtimeWorld.add(runtime)\n  }\n\n  /** Remove a runtime entry, closing it once its runs finish; `workspace` is permanent. */\n  async removeRuntime(name: string): Promise<void> {\n    if (this.isShuttingDown()) throw new Error('Workspace is closed')\n    await this.runtimeWorld.remove(name)\n  }\n\n  /**\n   * Install a CLI under a head word, fully separate from mounts. The\n   * name is the dispatch key (two installs of one spec under different\n   * names are two accounts); config validates through the spec's\n   * configModel, fail loud at install time.\n   */\n  registerCli(name: string, spec: CLI, config: Record<string, unknown> | null = null): CLIInstall {\n    if (this.isShuttingDown()) throw new Error('Workspace is closed')\n    return this.registry.clis.install(name, spec, config)\n  }\n\n  /** Remove an installed CLI and close its accessor; its head word stops\n   * resolving (127). */\n  async unregisterCli(name: string): Promise<void> {\n    if (this.isShuttingDown()) throw new Error('Workspace is closed')\n    await this.registry.clis.uninstall(name)\n  }\n\n  /** Snapshot of the installed CLIs keyed by head word. */\n  clis(): Map<string, CLIInstall> {\n    return this.registry.clis.items()\n  }\n\n  /**\n   * What the hidden recorder holds, oldest first: a `command` entry when a\n   * command a line reads starts and a `result` entry when it ends, naming\n   * it as its `parent`, and with `vfs` a `vfs` entry for every call it made\n   * to a mount. `sessionId` keeps one session's entries, `since`\n   * those at or after an epoch millisecond, `last` the newest that many,\n   * never more than HISTFILESIZE. Mirrors Python's `Workspace.history`.\n   */\n  async history(\n    options: { sessionId?: string; since?: number; last?: number; vfs?: boolean } = {},\n  ): Promise<JsonObject[]> {\n    const { sessionId, since, last, vfs = false } = options\n    const kinds = new Set<unknown>([EVENT_COMMAND, EVENT_RESULT, ...(vfs ? [EVENT_VFS] : [])])\n    const picked = (await this.observer.events(sessionId)).filter(\n      (e) =>\n        kinds.has(e.type) &&\n        (since === undefined || (typeof e.timestamp === 'number' ? e.timestamp : 0) >= since),\n    )\n    const ke