st,\n      sessionId === undefined ? this.callSession() : this.sessionManager.get(sessionId),\n    )\n  }\n\n  private sessionProcesses(session: SessionState): SessionProcesses {\n    const parentPid = session.processId\n    const processes = this.processTable.forSession(session.sessionId, () => session.processes)\n    return Object.freeze({\n      ...processes,\n      depth: session.processDepth,\n      spawn: (request: SpawnRequest) => {\n        processes.checkSpawn()\n        const child = session.fork()\n        child.processId = parentPid\n\n        return this.spawnForSession(request, child)\n      },\n    })\n  }\n\n  private spawnForSession(request: SpawnRequest, session: SessionState): ChildProcess {\n    if (this.isShuttingDown()) throw new Error('Workspace is closed')\n    if (session.processDepth >= 16) throw new Error('process nesting limit (16) reached')\n    const argv = [...request.argv]\n    literalTree(argv)\n    const head = argv[0] ?? ''\n    const name = head.startsWith(`${BIN_PREFIX}/`) ? head.slice(BIN_PREFIX.length + 1) : head\n    if (!name.includes('/')) {\n      if (\n        program(name, session, this.registry) === null &&\n        lookup(name, session, this.registry) !== Consumer.EXTERNAL\n      )\n        throw enoent(head)\n      argv[0] = name\n    }\n    const cwd = request.cwd ?? PathSpec.fromStrPath(session.cwd)\n    const inheritedEnv = request.replaceEnv === true ? {} : envSnapshot(session)\n    const child = session.fork({\n      cwd: cwd.virtual,\n      processDepth: session.processDepth + 1,\n      vars: varsFromEnv(inheritedEnv),\n      functions: {},\n    })\n    if (!Object.hasOwn(inheritedEnv, 'PWD')) child.vars.set('PWD', makeVar(cwd.virtual, new Set()))\n    child.aliases = {}\n    // The child's stdout is its handle's result, as a typed line's is the\n    // terminal, so the command limits bound what it hands back wherever\n    // the parent's own output goes.\n    child.terminalOutput = true\n    const caller = sessionCaller(child, this.sessionManager)\n    const input = new ProcessInput(this.io.bufferBytes),\n      output = new ProcessOutput(request.mergeStderr, this.io.bufferBytes),\n      abort = new AbortController()\n    const env = request.env === undefined ? undefined : { ...request.env }\n    const owner = this.sessionManager.get(session.sessionId)\n    const admission = this.processTable.forSession(session.sessionId, () => owner.processes)\n    const process = this.processTable.start({\n      sessionId: session.sessionId,\n      command: shellJoin(argv),\n      cwd,\n      parent: session.processId,\n      limit: session.processes.max,\n      cancel: () => {\n        abort.abort()\n        input.stop()\n        output.stop()\n      },\n      run: async () => {\n        try {\n          await this.jobTable.claim()\n          await this.ensureSessionsLoaded()\n          if (this.sessionManager.get(session.sessionId) !== owner)\n            throw new Error(\n              'session changed during hydration; retry spawn after ensureSessionsLoaded',\n            )\n          admission.checkSpawn()\n          // The handle bound itself around this run; the caller captured at\n          // spawn holds the spawning one's.\n          const { process: runner } = currentCaller()\n          const bound = { ...caller, process: runner }\n          const result = await runWithCaller(bound, async () => {\n            const view = sessionView(child)\n            for (const [name, value] of Object.entries(env ?? {})) {\n              await view.set(name, value)\n              await view.mark(name, VarAttr.Export, true)\n            }\n            return runAsProgram(child, () =>\n              executeLine(\n                this.executeEnv(),\n                shellJoin(argv),\n                {\n                  sessionId: session.sessionId,\n                  stdin: input.stream(),\n                  sink: output,\n                  signal: abort.signal,\n                },\n                argv,\n              ),\n            )\n          })\n          return result.exitCode\n        } finally {\n          input.stop()\n          output.end()\n        }\n      },\n    })\n    child.processId = process.record.id.pid\n    child.shellPid = process.record.id.pid\n    return new ChildProcess(process, input, output, (signal) => {\n      process.terminate(signal)\n    })\n  }\n\n  /**\n   * A program's own file call: the sandboxed runtimes' sole data path\n   * (quickjs, pyodide, monty), which `ctx.vfs` carries into a run.\n   *\n   * Routes through the dispatcher itself, not the raw Files facade, so\n   * runtime journal replay stays open during close and sandbox I/O takes\n   * the same path as shell commands: cache read-through on reads,\n   * post-write invalidation, and mount-mode enforcement narrowed by the\n   * current session all come from the Dispatcher. Mirrors Python's\n   * `Workspace._program_dispatch`.\n   *\n   * @param issuer rides every op as the `issuer` kwarg, which the\n   *   dispatcher lifts onto its context and never forwards to a backend:\n   *   it is how a profile policy's own reads reach its `preVfs` marked as\n   *   its own, as an argument rather than ambient state.\n   * @param dispatcher the dispatcher, bound to a session when one is named.\n   * @param changes what every op says of its caller: the command running the\n   *   program, so a rule scoped to `python3` reaches its `open()`, or a\n   *   policy deciding.\n   */\n  private programDispatch(\n    issuer?: symbol,\n    dispatcher: Dispatcher = this.dispatcher,\n    changes: Partial<Caller> | null = null,\n  ): DispatchFn {\n    return (name, path, args = [], kwargs = {}, report) =>\n      dispatcher.dispatch(\n        name,\n        path,\n        args,\n        issuer === undefined ? kwargs : { ...kwargs, issuer },\n        report,\n        changes === null ? undefined : { ...currentCaller(), ...changes },\n      )\n  }\n\n  // ── Public accessors aligned with Python's Workspace API ────────────\n\n  /**\n   * The workspace's admission policies; add() registers more. Ordered,\n   * built-ins first; on a pre method the first Deny wins, and adding a\n   * policy can only tighten the workspace.\n   */\n  get policies(): Policies {\n    return this.registry.policies\n  }\n\n  /**\n   * The host's entry point on asked commands: `list()` the requests waiting,\n   * `grant(id, scope)` or `deny(id)` one, and the agent's retry passes\n   * or is refused.\n   */\n  get decisions(): Decisions {\n    return this.registry.decisions\n  }\n\n  /** The agent tools as the default session; `Session.tools` for another. */\n  get tools(): MirageToolOperations {\n    return this.sessionTools(null)\n  }\n\n  /**\n   * The one tool table a session has, made on first use. Every caller in\n   * the process shares it, so a file the agent read through one is\n   * guarded when it writes through another. Closing the session drops it.\n   * Null is the default session as it is when each call runs, so its\n   * table keeps working when a snapshot load or an attach re-keys the\n   * default; an id stays that session.\n   *\n   * @internal `Session.tools` is the entry point.\n   */\n  sessionTools(sessionId: string | null): MirageToolOperations {\n    let tools = this.toolTables.get(sessionId)\n    if (tools === undefined) {\n      tools = new MirageToolOperations(new Session(this, sessionId))\n      this.toolTables.set(sessionId, tools)\n    }\n    return tools\n  }\n\n  /**\n   * The read history the agent tools keep for one session. Every guarded\n   * table of the session shares it, the one following the default\n   * included, so a read through `ws.tools` guards a write through\n   * `new Session(ws, id).tools`. Sessions load first, so the default's id\n   * is final before it is looked up. Closing the session drops it, and a\n   * snapshot restore drops them all; null is the default as it is now.\n   *\n   * @internal `Session.tools` is the entry point.\n   */\n  async sessionReads(sessionId: string | null): Promise<FileVersionTracker> {\n    await this.ensureSessionsLoaded()\n    const id = sessionId ?? this.defaultSessionId\n    let reads = this.reads.get(id)\n    if (reads === undefined) {\n      reads = new FileVersionTracker(this.vfs.forSession(id))\n      this.reads.set(id, reads)\n    }\n    return reads\n  }\n\n  get cwd(): string {\n    return this.sessionManager.cwd\n  }\n\n  set cwd(value: string) {\n    this.sessionManager.cwd = value\n  }\n\n  get env(): Record<string, string> {\n    return this.sessionManager.env\n  }\n\n  set env(value: Record<string, string>) {\n    this.sessionManager.env = value\n  }\n\n  /**\n   * The base profile a session is created under, which the inline\n   * `permissions`/`mounts` options then layer onto: the profile as\n   * named, else the workspace default.\n   */\n  private baseProfile(profile: string | SessionProfile | null): SessionProfile | null {\n    if (profile === null && this.defaultProfileName !== null) {\n      return this.profiles[this.defaultProfileName] ?? null\n    }\n    return resolveProfile(this.profiles, profile)\n  }\n\n  /**\n   * A session's profile compiled over the workspace's `processes`, the one\n   * way a profile reaches a session. `profile` is what the caller named,\n   * for the profile's name. Mirrors Python's `_compile`.\n   */\n  private compile(\n    effective: SessionProfile | null,\n    profile: string | SessionProfile | null,\n  ): CompiledProfile {\n    return compileProfile(effective, this.profileName(profile), this.workspaceProcesses)\n  }\n\n  /**\n   * The name of the profile `baseProfile` resolves, which its programs\n   * read as `ctx.profile`; empty for a profile document passed without\n   * one.\n   */\n  private profileName(profile: string | SessionProfile | null): string {\n    if (typeof profile === 'string') return profile\n    if (profile === null && this.defaultProfileName !== null) return this.defaultProfileName\n    if (profile === null && DEFAULT_PROFILE in this.profiles) return DEFAULT_PROFILE\n    return ''\n  }\n\n  /**\n   * Create a session under one profile, with an optional inline\n   * document of its own.\n   *\n   * The profile is a name from the workspace's `profiles`, or the\n   * workspace default when none is named, or a profile document. The\n   * inline `permissions` and `mounts` may add ask and deny rules, hides\n   * and weaker modes; they may never add an allow entry, which is the\n   * one rule about combining two documents. `mounts` is sugar for\n   * `permissions.mounts`: a mapping assigns each prefix a mode ('read',\n   * 'write', 'exec', or the filesystem aliases 'r', 'rw', 'rwx'), which\n   * may only be weaker than the mount's own. A mount the mapping omits\n   * keeps its own mode, so this narrows and never confines; a profile\n   * that must keep a session away from a mount hides it. Throws\n   * PolicyError on an unknown profile name, or on an inline document\n   * with an allow list.\n   */\n  createSession(\n    sessionId: string,\n    options: {\n      mounts?: ReadonlyMap<string, unknown> | Record<string, unknown> | null\n      profile?: string | SessionProfile | null\n      permissions?: SessionProfile | null\n    } = {},\n  ): SessionState {\n    const base = this.baseProfile(options.profile ?? null)\n    let inline: SessionProfile | null = options.permissions ?? null\n    if (options.mounts != null) {\n      inline = withInline(inline, { mounts: parseProfileMounts(options.mounts) })\n    }\n    const compiled = this.compile(\n      withInline(base, inline, this.workspaceProcesses),\n      options.profile ?? null,\n    )\n    checkCliVerbs(compiled.policies.commands, this.cliVerbs())\n    return this.sessionManager.create(sessionId, { profile: compiled })\n  }\n\n  /**\n   * The verbs each installed CLI declares, keyed by head word.\n   *\n   * Read at `createSession` rather than at compile time because a CLI is\n   * registered on the workspace after it is built.\n   */\n  /**\n   * One session's two entry points: `shell` and `vfs` bound to it.\n   *\n   * Creates the session under the given profile when the id is new (the\n   * same call as `createSession`), and adopts it as is when it exists.\n   * Options for an existing session are refused rather than ignored: a\n   * profile is set once, at creation, and the object it returns must not look like\n   * it narrowed a session it merely adopted. The session store is\n   * hydrated first, so a session a previous process persisted is\n   * adopted with its stored profile rather than recreated over it; that\n   * is why this is async where `createSession` is not.\n   */\n  async session(\n    sessionId: string,\n    options: Parameters<Workspace['createSession']>[1] = {},\n  ): Promise<Session> {\n    await this.ensureSessionsLoaded()\n    if (this.sessionManager.has(sessionId)) {\n      if (options.mounts != null || options.profile != null || options.permissions != null) {\n        throw new Error(`session '${sessionId}' exists; its profile was set when it was created`)\n      }\n      return new Session(this, sessionId)\n    }\n    this.createSession(sessionId, options)\n    return new Session(this, sessionId)\n  }\n\n  private cliVerbs(): ReadonlyMap<string, ReadonlySet<string>> {\n    const out = new Map<string, ReadonlySet<string>>()\n    for (const [name, install] of this.registry.clis.items()) {\n      out.set(name, new Set(install.cli.spec.subcommands.map((child) => child.name)))\n    }\n    return out\n  }\n\n  getSession(sessionId: string): SessionState {\n    return this.sessionManager.get(sessionId)\n  }\n\n  /** The workspace's `network` setting, as it was written. */\n  get network(): NetworkSetting {\n    return this.networkSetting\n  }\n\n  /** The workspace's `system_time`, as it was written; null for the host's time. */\n  get systemTime(): string | null {\n    return this.systemTimeSetting\n  }\n\n  /** The profile table every session here runs under. */\n  get profiles(): Readonly<Record<string, SessionProfile>> {\n    return this.profilesInternal\n  }\n\n  /**\n   * Define a named profile, or replace the one the name has.\n   *\n   * Compilation succeeds before the table changes. A session created or\n   * set to the name afterwards runs the new document under that name;\n   * a live session keeps the rules it was compiled with until\n   * `setSessionProfile` moves it. This is a host-side operation, like\n   * creating a session.\n   */\n  setProfile(name: string, profile: SessionProfile): void {\n    checkName('profile name', name)\n    // A typed caller does not pass the parser, so this entry point repeats\n    // its two checks: the old keys are told where they went, and a\n    // policy block is whole.\n    const legacy = profile as { script?: unknown; runtime?: unknown }\n    if (legacy.script !== undefined || legacy.runtime !== undefined) {\n      throw new PolicyError(\n        `profile '${name}': script and runtime are now a policy block, ` +\n          `policy: {pre_command: [{script: <file>, runtime: <runtime>}]}`,\n      )\n    }\n    if (profile.policy != null) {\n      parseProfilePolicy(profile.policy, `profile '${name}' policy`, true)\n    }\n    if (profile.commandLimits != null) {\n      checkCommandLimits(profile.commandLimits, `profile '${name}'`, true)\n    }\n    // Its env names pointers in the workspace env grammar, so the\n    // sources it names are checked here too, before a session runs.\n    for (const entry of Object.values(varsFromEntries(profile.env ?? {}))) {\n      if (\n        entry.managed !== undefined &&\n        !Object.hasOwn(this.declaredSecretSources, entry.managed.source)\n      ) {\n        sourceFor(entry.managed.source)\n      }\n    }\n    checkCliVerbs(this.compile(profile, name).policies.commands, this.cliVerbs())\n    this.profilesInternal[name] = profile\n  }\n\n  /**\n   * Replace a live session's permissions, including its policy runtime.\n   * Compilation succeeds before anything changes. Cwd/env presets apply only\n   * at creation; cwd, variables, functions and history survive this change.\n   * Null selects the workspace default; an empty document clears restrictions.\n   * This is a host-side operation, like creating a session.\n   */\n  async setSessionProfile(\n    sessionId: string,\n    profile: string | SessionProfile | null,\n  ): Promise<SessionState> {\n    if (this.isShuttingDown()) throw new Error('Workspace is closed')\n    const compiled = this.compile(this.baseProfile(profile), profile)\n    checkCliVerbs(compiled.policies.commands, this.cliVerbs())\n    const wasDefault = sessionId === this.defaultSessionId\n    await this.ensureSessionsLoaded()\n    if (this.isShuttingDown()) throw new Error('Workspace is closed')\n    if (wasDefault) sessionId = this.defaultSessionId\n    const session = await this.sessionManager.setProfile(sessionId, compiled)\n    this.processTable.revokeSession(sessionId)\n    return session\n  }\n\n  listSessions(): SessionState[] {\n    return this.sessionManager.list()\n  }\n\n  /**\n   * The lines the workspace keeps, oldest first: every one not ended yet,\n   * and the newest ended ones, as its store keeps them, so a daemon that\n   * does not hold the workspace's lease lists the same ones; the holder\n   * reads its own as they are now. A session's or those in a state when\n   * named.\n   */\n  async lines(filter: { sessionId?: string; state?: LineState } = {}): Promise<Line[]> {\n    const found = new Map<string, Line>()\n    for (const line of await this.jobTable.store.findLines(filter.sessionId)) {\n      found.set(line.id.value, line)\n    }\n    if (this.jobTable.claimed) {\n      for (const line of this.lineTable.lines(filter.sessionId)) found.set(line.id.value, line)\n    }\n    return [...found.values()]\n      .filter((line) => filter.state === undefined || line.state === filter.state)\n      .sort((a, b) => a.startedAt - b.startedAt)\n  }\n\n  /** One line's record, while the workspace keeps it. */\n  async line(id: LineId): Promise<Line | null> {\n    const own = this.jobTable.claimed ? this.lineTable.get(id) : null\n    return own ?? (await this.jobTable.store.getLine(id))\n  }\n\n  /**\n   * The jobs the workspace's sessions list, as `jobs` does: each until its\n   * ending is reported; a session's, those in a state or those a line\n   * started when named. A daemon that does not hold the workspace's lease\n   * reads each session's list from the store first.\n   */\n  async jobs(\n    filter: { sessionId?: string; state?: JobState; lineId?: LineId } = {},\n  ): Promise<Job[]> {\n    if (!this.jobTable.claimed) {\n      // Every session the store keeps a list for, and every one this table\n      // lists jobs of, whose list may have gone with its session.\n      const ids =\n        filter.sessionId !== undefined\n          ? [filter.sessionId]\n          : [\n              ...new Set([\n                ...(await this.jobTable.store.sessions()),\n                ...this.jobTable.allJobs().map((job) => job.sessionId),\n              ]),\n            ].sort(compareCodePoints)\n      for (const id of ids) await this.jobTable.sync(id)\n    }\n    const handles =\n      filter.sessionId === undefined\n        ? this.jobTable.allJobs()\n        : this.jobTable.listJobs(filter.sessionId)\n    return handles\n      .filter((job) => !job.reported)\n      .map((job) => job.record)\n      .filter(\n        (job) =>\n          (filter.state === undefined || job.state === filter.state) &&\n          (filter.lineId === undefined || job.line?.value === filter.lineId.value),\n      )\n  }\n\n  /** One job's record, while a session lists it. */\n  async job(id: JobId): Promise<Job | null> {\n    return (\n      (await this.jobs()).find(\n        (job) => job.id.workspaceId === id.workspaceId && job.id.console === id.console,\n      ) ?? null\n    )\n  }\n\n  /**\n   * The processes the workspace keeps, by pid: every live one, and the\n   * newest ended ones, as its store keeps them, so a daemon that does not\n   * hold the workspace's lease lists the same ones; the holder reads its\n   * own as they are now, its machines scanned first. A session's, those in\n   * a state, those a line ran, those a job ran (its own and every one under\n   * it, while a session lists it) or those run on a machine when named.\n   */\n  async processes(\n    filter: {\n      sessionId?: string\n      state?: ProcessState\n      lineId?: LineId\n      jobId?: JobId\n      machine?: MachineId\n    } = {},\n  ): Promise<Process[]> {\n    const claimed = this.jobTable.claimed\n    if (claimed) await this.processTable.scan()\n    const found = new Map<number, Process>()\n    for (const process of await this.jobTable.store.findProcesses(filter.sessionId)) {\n      found.set(process.id.pid, process)\n    }\n    if (claimed) {\n      for (const process of this.processTable.records()) {\n        if (filter.sessionId === undefined || process.sessionId === filter.sessionId)\n          found.set(process.id.pid, process)\n      }\n    }\n    const records = [...found.values()].sort((a, b) => a.id.pid - b.id.pid)\n    let tree: Set<number> | null = null\n    if (filter.jobId !== undefined) {\n      const pid = (await this.job(filter.jobId))?.pid ?? null\n      tree = new Set()\n      if (pid !== null && claimed) {\n        tree = this.processTable.tree(pid)\n      } else if (pid !== null) {\n        tree = new Set([\n          pid,\n          ...records.filter((process) => process.ancestors.includes(pid)).map((p) => p.id.pid),\n        ])\n      }\n    }\n    return records.filter(\n      (process) =>\n        (filter.state === undefined || process.state === filter.state) &&\n        (filter.lineId === undefined || process.line?.value === filter.lineId.value) &&\n        (tree === null || tree.has(process.id.pid)) &&\n        (filter.machine === undefined || process.machine.toString() === filter.machine.toString()),\n    )\n  }\n\n  /** One process's record, while the workspace keeps it; none for another workspace's. */\n  async process(id: ProcessId): Promise<Process | null> {\n    if (id.workspaceId !== this.wsId) return null\n    const own = this.jobTable.claimed\n      ? (this.processTable\n          .records()\n          .find(\n            (process) => process.id.workspaceId === id.workspaceId && process.id.pid === id.pid,\n          ) ?? null)\n      : null\n    return own ?? (await this.jobTable.store.getProcess(id))\n  }\n\n  /**\n   * The machines the workspace runs programs on, each as a check of it finds\n   * it now: its own host first, which Mirage always manages, then every\n   * machine `machines:` names, checked at once; only `machine` when named.\n   * Mirrors Python's `Workspace.machines`.\n   */\n  async machines(machine?: MachineId): Promise<Machine[]> {\n    const host = this.processTable.machine\n    const found: Machine[] =\n      machine === undefined || machine.toString() === host.toString()\n        ? [{ id: host, state: 'managed', checkedAt: this.clock.now() }]\n        : []\n    return [\n      ...found,\n      ...(await this.machineTable.check(() => this.clock.now(), machine?.toString())),\n    ]\n  }\n\n  async closeSession(sessionId: string): Promise<void> {\n    // The manager refuses the default and an unknown id first; a session\n    // that did close takes its jobs with it, so a later session reusing\n    // the id inherits nothing. Its lines are cancelled first, as a hangup\n    // ends a terminal's foreground job.\n    if (sessionId !== this.defaultSessionId) await this.cancel(sessionId)\n    await this.sessionManager.close(sessionId)\n    await this.documents.releaseSession(sessionId)\n    await this.jobTable.closeSession(sessionId)\n    this.toolTables.delete(sessionId)\n    this.reads.delete(sessionId)\n  }\n\n  /**\n   * Hydrate sessions from the session store (idempotent). The discovery\n   * record resolves first so a minted default session id can adopt the\n   * stored pointer before hydration keys off it. The first call also starts\n   * stopping what lapsed instances of the workspace left running\n   * (`JobTable.stopLapsed`). Closing waits for the record's write in\n   * flight, so it never races the state's drop.\n   */\n  async ensureSessionsLoaded(): Promise<void> {\n    this.jobTable.stopLapsed()\n    this.metaWrite ??= this.meta.ensure().finally(() => {\n      this.metaWrite = null\n    })\n    await this.metaWrite\n    await this.sessionManager.ensureLoaded()\n  }\n\n  /**\n   * What a line would do under a session's profile, without running any of\n   * it: the line's verdict and its parse tree.\n   *\n   * The dry run of the gate every command passes through, so this and the\n   * refusal an agent would read come out of one place and cannot disagree.\n   * It runs no command, expands nothing, spends no grant and puts no\n   * question to a host, which is what makes it safe to call about a line\n   * nobody typed; a policy deciding it reads for real but changes nothing\n   * (`DryRun`). The line carries\n   * the verdict its result would, every answer at `preExecute` and its\n   * parse tree, each command with every policy's answer to it and the\n   * runtime that would run it. A line a rule refuses, or that waits on the\n   * host, is never placed, as it is never placed when it runs, and a\n   * placement that refuses the line gives it the placement's refusal. A\n   * hidden path is no path to any of it. `session.explain` is\n   * the same dry run for each of a session's entry points.\n   *\n   * Host-side only. The structure of a profile's rules is an operator's\n   * business, so there is no builtin an agent can type to read it.\n   */\n  async explain(line: string, sessionId = ''): Promise<ShellExplanation> {\n    await this.ensureSessionsLoaded()\n    // Without task isolation the bindings would reach other tasks' ops; there\n    // the deciding mark rides each method's own files and program alone.\n    if (!asyncContextIsolatesTasks) return this.explained(line, sessionId)\n    // Judged inside a line, as the line runs: an ask a deciding policy's\n    // read meets refuses like a deny and records nothing.\n    return runWithRefusalSink(\n      () => undefined,\n      () => runExplaining(DryRun.DECIDING, () => this.explained(line, sessionId)),\n    )\n  }\n\n  /** `explain`'s judging, run with its policies deciding. */\n  private async explained(line: string, sessionId: string): Promise<ShellExplanation> {\n    const session = this.getSession(sessionId === '' ? this.defaultSessionId : sessionId)\n    const parser = new ParseScope()\n    try {\n      const aliases = expandingAliases(session)\n      const reparse = (text: string): TSNodeLike => parser.parse(text, aliases)\n      const root = parser.parse(line, aliases)\n      const verdicts = await explainLine(\n        root,\n        session,\n        this.registry,\n        this.namespace,\n        reparse,\n        false,\n        false,\n      )\n      if (holds(verdicts.map((one) => one.judgment))) {\n        // The run leaves a held line on its static bindings for the gate to\n        // answer (`Router.decide`), whole when they take it whole.\n        const whole = wholeLineRuntime(this.registry.runtimeBindings)\n        const wholeLine = whole !== null\n        const judged = await explainLine(\n          root,\n          session,\n          this.registry,\n          this.namespace,\n          reparse,\n          wholeLine,\n        )\n        return explainedLine(\n          line,\n          judged,\n          wholeLine ? judged : verdicts,\n          (one) => (wholeLine ? this.router.placementFor(one, this.router.unplaced()) : ['', '']),\n          reparse,\n          wholeLine,\n        )\n      }\n      const [answers, placed] = await this.router.placement(line, session, () =>\n        lineJudgments(\n          root,\n          session,\n          this.registry,\n          this.namespace,\n          { claimed: [], parent: null, origin: null },\n          reparse,\n        ),\n      )\n      // The run reads a line its placed runtime takes whole as typed, and\n      // that reading is its only gate (`admitLine`).\n      const wholeLine = !('kind' in placed) && wholeLineRuntime(placed.bindings) !== null\n      const judged = await explainLine(\n        root,\n        session,\n        this.registry,\n        this.namespace,\n        reparse,\n        wholeLine,\n      )\n      if ('kind' in placed) {\n        const refused = placementRefused(placed, line)\n        return {\n          ...explainedLine(line, judged, verdicts, () => ['', ''], reparse),\n          answers,\n          outcome: placed.kind === 'pending' ? Outcome.ASK : Outcome.DENY,\n          reason: placed.reason,\n          source: '',\n          refusal: refused.refusal,\n          exitCode: refused.exitCode,\n          stderr: refused.stderrText,\n        }\n      }\n      const said = explainedLine(\n        line,\n        judged,\n        wholeLine ? judged : verdicts,\n        this.router.placements(judged, placed),\n        reparse,\n        wholeLine,\n      )\n      if (wholeLine && said.outcome === Outcome.ALLOW) {\n        // A command routed off the runtime that runs the line whole\n        // refuses the line, as the run's admission does.\n        for (const one of judged) {\n          const off = await offLineRefusal(one, (each) => this.router.offLine(each, placed))\n          if (off?.refusal == null) continue\n          return {\n            ...said,\n            answers,\n            outcome: Outcome.DENY,\n            reason: off.refusal.reason,\n            source: '',\n            refusal: off.refusal,\n            exitCode: off.exitCode,\n            stderr: decodeText(off.stderr),\n          }\n        }\n      }\n      return { ...said, answers }\n    } finally {\n      parser.release()\n    }\n  }\n\n  get workspaceId(): string {\n    return this.wsId\n  }\n\n  get defaultSessionId(): string {\n    return this.sessionManager.defaultId\n  }\n\n  get stateStore(): WorkspaceStateStore {\n    return this.stateStoreInternal\n  }\n\n  /**\n   * Snapshot restore: adopt the snapshot's default session identity and\n   * point the discovery record at it.\n   */\n  async adoptDefaultSession(sessionId: string): Promise<void> {\n    await this.meta.adoptDefault(sessionId)\n  }\n\n  /**\n   * Snapshot restore: every session the snapshot restores is a new one\n   * to the agent tools, so none keeps what was read before.\n   *\n   * @internal\n   */\n  forgetReads(): void {\n    this.reads.clear()\n  }\n\n  /** Write every session's durable fields through to the session store. */\n  flushSessions(): Promise<void> {\n    return this.sessionManager.flush()\n  }\n\n  mounts(): readonly MountEntry[] {\n    return this.registry.allMounts()\n  }\n\n  mount(prefix: string): MountEntry {\n    return this.registry.mountFor(prefix)\n  }\n\n  attachEventRuntime(runtime: EventRuntime): void {\n    if (this.isShuttingDown()) throw new Error('Workspace is closed')\n    this.eventManager.attach(runtime)\n  }\n\n  async detachEventRuntime(): Promise<void> {\n    await this.eventManager.detach()\n  }\n\n  events(path: string | PathSpec | readonly (string | PathSpec)[]): AsyncIterable<FileEvent> {\n    if (this.isShuttingDown()) throw new Error('Workspace is closed')\n    return this.eventManager.events(path)\n  }\n\n  async notify(change: FileEvent): Promise<void> {\n    if (this.isShuttingDown()) throw new Error('Workspace is closed')\n    await this.eventManager.notify(change)\n  }\n\n  /**\n   * Add a mount to a running workspace.\n   *\n   * The runtime entry point runs the same read-policy verdict the constructor\n   * does: a mount added here is no more able to declare a policy its\n   * backend cannot honour than one declared in config.\n   *\n   * `index` is the mount's own index; left out, the workspace's.\n   *\n   * `write` is the mount