      "path": "typescript/packages/dsh/package.json",
      "content": "{\n  \"name\": \"@struktoai/mirage-dsh\",\n  \"version\": \"0.0.9-alpha.1\",\n  \"description\": \"DeepSeek Harness (dsh) providers backed by a mirage workspace: ctx.fs and ctx.shell over mounts\",\n  \"homepage\": \"https://github.com/strukto-ai/mirage#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/strukto-ai/mirage/issues\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/strukto-ai/mirage.git\",\n    \"directory\": \"typescript/packages/dsh\"\n  },\n  \"license\": \"Apache-2.0\",\n  \"author\": \"Zecheng Zhang <zecheng@strukto.ai>\",\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \"^22.20 || ^24.12 || >=25\"\n  },\n  \"main\": \"./dist/index.js\",\n  \"types\": \"./dist/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./dist/index.d.ts\",\n      \"import\": \"./dist/index.js\"\n    },\n    \"./service\": {\n      \"types\": \"./dist/plugin/service.d.ts\",\n      \"import\": \"./dist/plugin/service.js\"\n    },\n    \"./fs\": {\n      \"types\": \"./dist/plugin/fs.d.ts\",\n      \"import\": \"./dist/plugin/fs.js\"\n    },\n    \"./shell\": {\n      \"types\": \"./dist/plugin/shell.d.ts\",\n      \"import\": \"./dist/plugin/shell.js\"\n    },\n    \"./spill-store\": {\n      \"types\": \"./dist/plugin/spill-store.d.ts\",\n      \"import\": \"./dist/plugin/spill-store.js\"\n    },\n    \"./subprocess\": {\n      \"types\": \"./dist/plugin/subprocess.d.ts\",\n      \"import\": \"./dist/plugin/subprocess.js\"\n    }\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"files\": [\n    \"dist\",\n    \"cordis.patch.yml\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsup\",\n    \"test\": \"vitest run\",\n    \"typecheck\": \"tsc --noEmit\"\n  },\n  \"dependencies\": {\n    \"@struktoai/mirage-core\": \"workspace:*\",\n    \"@struktoai/mirage-node\": \"workspace:*\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.0.4\",\n    \"@deepseek-ai/dsh-fs\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-shell\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-spill\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-subprocess\": \"0.2.0-rc.2\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.0.4\",\n    \"@deepseek-ai/dsh-fs\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-shell\": \"0.2.0-rc.2\",\n    \"@deepseek-ai/dsh-spill\": \"0.2.0-rc.2\",\n    \"tsup\": \"^8.5.0\",\n    \"typescript\": \"^6.0.0\",\n    \"vitest\": \"^4.1.12\",\n    \"@deepseek-ai/dsh-subprocess\": \"0.2.0-rc.2\"\n  }\n}\n"
