    {
      "path": "typescript/packages/dsh/cordis.patch.yml",
      "content": "# The mirage bundle patch. Applied over dsh-base by `dsh --profile <name>`\n# after `dsh plugin --profile <name> add @struktoai/mirage-dsh`: it swaps\n# the filesystem and shell providers for mirage-backed ones, so dsh's file\n# tools and bash tool operate on a workspace of mounted VFS instead\n# of the host disk.\n#\n# Override the `mirage` row's config in the profile's own cordis.patch.yml\n# to mount real VFS (the block form is `vfs` registry name,\n# `mode`, and the VFS's `config`; `!!js` expressions resolve env vars\n# at mount time):\n#\n#   - id: mirage\n#     config:\n#       mounts:\n#         /tmp: { VFS: ram, mode: exec }\n#         /slack:\n#           VFS: slack\n#           mode: read\n#           config: { token: !!js process.env.SLACK_BOT_TOKEN }\n#       runtimes:\n#         - { name: monty, captures: [python, python3] }\n#\n# A profile may also carry a permission document, which is what turns\n# mirage's allow/ask/deny into a policy for this bundle. Roles go under\n# `profiles`, and `profile` names the one a session gets by default:\n#\n#   - id: mirage\n#     config:\n#       profiles:\n#         agent:\n#           commands:\n#             allow: [cat, ls, grep, rm]\n#             ask:\n#               - { commands: [rm], reason: deletes are reviewed }\n#             deny:\n#               - { commands: [git push], reason: no publishing }\n#       profile: agent\n#\n# An `ask` rule is put to the human through dsh's own approval channel\n# (`ctx.approval`), so the prompt the agent triggers is the one dsh\n# already shows for its escalations. It quotes the line word by word as\n# a shell would read it back, so a name carrying a space or a newline\n# cannot pass itself off in the prompt as two operands or two lines.\n# `allowed-once` runs the line;\n# a rejection, a dismissal and an unanswerable ask all refuse it. With\n# no approval plugin composed the ask has nowhere to go, so it stays a\n# pending record the host answers through `ctx.mirage.decisions`\n# (`pending()`, then `answer(id, outcome, scope)`) — deliberately not a\n# refusal, since rewriting an `ask` rule as a `deny` would change what\n# the document says. A question never outlives the run that raised it:\n# the run's abort signal goes to the channel with the request and bounds\n# the ledger's wait, so a line still unanswered when its timeout expires\n# comes back as the kill, and a yes arriving after that is dropped\n# rather than banked for the next identical line.\n#\n# Two facts about how the mirage providers read the surrounding dsh\n# composition, neither of which needs a row here:\n#\n#   * The standing file policy is enforced, not merely reported. Both\n#     seams narrow every mount grant to read for a `read-only` call\n#     (leaving the null sink writable, as that mode's definition\n#     requires), so dsh-base's `DSH_PERMISSION_MODE=read-only` now\n#     actually confines a mirage world instead of being ignored. The\n#     policy's `workspaceRoot` is a directory on the host and is never\n#     consulted: the mounts and their modes are the boundary here.\n#\n#   * A workdir dsh resolved on its own machine (an unspecified one\n#     comes from the calling session's cwd) names nothing in this world,\n#     so it is ignored in favour of the workspace default rather than\n#     run in a directory the agent cannot reach.\n#\n# ctx.subprocess shares the workspace's argv admission and process supervisor.\n# Termination covers managed Mirage runners. Native OS descendant tracking and\n# PTYs are unsupported; this provider refuses worlds with native/remote reach.\n- id: subprocess\n  disabled: true\n\n# The host filesystem and bash providers step aside; mirage provides the\n# same ctx.fs and ctx.shell seams over the workspace.\n- id: fs-sandbox\n  disabled: true\n\n- id: bash-sandbox\n  disabled: true\n\n# PowerShell and the ripgrep-based search tool run host subprocesses,\n# which the mirage world does not contain; the bash tool's grep covers\n# search inside the workspace.\n- id: pwsh-sandbox\n  disabled: true\n\n- id: tool-pwsh\n  disabled: true\n\n- id: tool-fs-search\n  disabled: true\n\n# Oversized tool results spill to the workspace, not to the host.\n#\n# The spill policy keeps a result over `maxInlineBytes` out of the\n# model's context by saving the full text and replacing the result with\n# a preview plus the locator, telling the model to read or grep it for\n# the rest. dsh-base stores that through `spill-local`, which writes\n# under the host's temporary directory — a path that names nothing in\n# this world, so the recovery the notice invites fails on a file the\n# model cannot open, and an oversized result becomes truncation with a\n# dead pointer. The mirage store writes through the same dispatcher every\n# other effect here passes, so the locator is an ordinary workspace path\n# and the tool that produced the output is the one that can go read it.\n#\n# `dir` moves the artifacts; the default rides the `/tmp` ram mount\n# below. A deployment that wants them out of the agent's reach puts\n# `dir` on a mount the session holds no grant for — mirage has no\n# permission bits to offer, so the mount table is the boundary.\n- id: spill-local\n  disabled: true\n\n- insert:\n    - id: mirage\n      name: '@struktoai/mirage-dsh/service'\n      config:\n        mounts:\n          /tmp: { vfs: ram, mode: exec }\n\n    - id: mirage-fs\n      name: '@struktoai/mirage-dsh/fs'\n\n    - id: mirage-subprocess\n      name: '@struktoai/mirage-dsh/subprocess'\n\n    - id: mirage-shell\n      name: '@struktoai/mirage-dsh/shell'\n\n    - id: mirage-spill\n      name: '@struktoai/mirage-dsh/spill-store'\n"
    },
    {
      "path": "typescript/packages/core/src/workspace/workspace/routing.ts",
      "content": "// ========= Copyright 2026 @ Strukto.AI All Rights Reserved. =========\n// Licensed under the Apache License, Version 2.0 (the \"License\");\n// you may not use this file except in compliance with the License.\n// You may obtain a copy of the License at\n//\n//     http://www.apache.org/licenses/LICENSE-2.0\n//\n// Unless required by applicable law or agreed to in writing, software\n// distributed under the License is distributed on an \"AS IS\" BASIS,\n// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n// See the License for the specific language governing permissions and\n// limitations under the License.\n// ========= Copyright 2026 @ Strukto.AI All Rights Reserved. =========\n\nimport { RouteError } from '../../runtime/routing/index.ts'\nimport type { RouteDecision } from '../../runtime/types.ts'\nimport type {\n  Ask,\n  Claimant,\n  CommandContext,\n  Deny,\n  Pending,\n  Route,\n  RouteContext,\n} from '../../policy/types.ts'\nimport { opQuestion, sameOccurrence } from '../../policy/decisions.ts'\nimport { agreed, commandRoute, settled } from '../../policy/policies.ts'\nimport type { Runtime } from '../../runtime/base.ts'\nimport { EXTERNAL_COMMANDS, WHOLE_LINE } from '../../runtime/constants.ts'\nimport { catchAll, routed, runtimeBindingsFor, wholeLineRuntime } from '../../runtime/table.ts'\nimport { PathSpec } from '../../types.ts'\nimport { mirageProgramAt, routedConsumer } from '../lookup/lookup.ts'\nimport { Consumer } from '../lookup/types.ts'\nimport { WorkspaceRuntime } from '../../runtime/workspace.ts'\nimport type { MountRegistry } from '../mount/registry.ts'\nimport type { Judged, Walked } from '../node/explain.ts'\nimport type { SessionState } from '../session/session.ts'\nimport type { ExecuteOptions } from './types.ts'\nimport type { Runtimes } from './runtimes.ts'\nimport { makeAbortError } from '../../utils/abort.ts'\n\n/**\n * The policy ladder for one typed line: runtime argument, the placement\n * stage (`preExecute`: the configured route policy as a built-in, then\n * the coded policies), then each command's first capturer. Mirrors the\n * Python `Router` in `workspace/routing.py`.\n *\n * `decide` returns the static bindings as the decision when nothing\n * decides (no runtime argument, nothing to consult), the stage's Deny when\n * a policy refuses the line, and the ledger's answer to its Ask when the\n * host refuses the line or has not answered yet; a nested eval inherits\n * the typed line's decision and never re-routes. The runtime argument is\n * the caller's own placement, so a Route is not asked for, but a coded\n * policy's Deny or Ask still holds the line. Admission comes first: a line\n * `held` reports refused or waiting on a question is left unplaced, for\n * the gate to answer. `judged` is\n * the line pass's reading of the line (`lineJudgments`), which gives\n * `preExecute` its commands; awaited only when there is a placement to\n * consult. `claimant` is\n * the line as a whole on its hand-off, so an approval of the line is\n * claimed there like a command's: kept for the retry of a line still\n * waiting on another question, spent when the line ends.\n */\n// The line's decision rides its evaluation's frame, which the walker\n// reads per command and a child evaluation forks with it: nested lines\n// never re-route. Declared here, where the decision is made, so the\n// frame's module imports no runtime.\ndeclare module '../frame.ts' {\n  interface ExecutionFrame {\n    routing?: RouteDecision<Runtime>\n  }\n}\n\n/** The machine a runtime would run a command on under a decision, as its id; empty for the workspace's own. */\nfunction machineOf(runtime: Runtime, decision: RouteDecision<Runtime>): string {\n  let machine\n  try {\n    machine = runtime.machineFor({\n      stdin: null,\n      flags: {},\n      cwd: PathSpec.fromStrPath('/'),\n      ...(decision.machine !== undefined ? { machine: decision.machine } : {}),\n    })\n  } catch (caught) {\n    console.debug(`${runtime.name}: no machine to explain:`, caught)\n    return ''\n  }\n  return machine === null ? '' : machine.toString()\n}\n\n/** A decision as it places each command on its own, its whole-line runtime left out. Mirrors Python's `_apart`. */\nfunction apart(decision: RouteDecision<Runtime>): RouteDecision<Runtime> {\n  const bindings = Object.create(null) as Record<string, Runtime | null>\n  for (const [name, runtime] of Object.entries(decision.bindings)) {\n    if (name !== WHOLE_LINE) bindings[name] = runtime\n  }\n  return { ...decision, bindings }\n}\n\nexport class Router {\n  private readonly registry: MountRegistry\n  private readonly runtimes: Runtimes\n\n  constructor(registry: MountRegistry, runtimes: Runtimes) {\n    this.registry = registry\n    this.runtimes = runtimes\n  }\n\n  async decide(\n    command: string,\n    options: ExecuteOptions,\n    session: SessionState,\n    judged: () => Promise<readonly [Walked, Judged[]][]>,\n    held?: () => Promise<boolean>,\n    claimant: Claimant | null = null,\n    signal?: AbortSignal,\n  ): Promise<RouteDecision<Runtime> | Deny | Pending> {\n    if (options.routingDecision !== undefined) return options.routingDecision\n    const policies = this.registry.policies\n    const placing = await policies.wantsFor('preExecute', session.sessionId)\n    const placed =\n      options.runtime === undefined && options.machine === undefined\n        ? null\n        : this.placed(options.runtime, options.machine)\n    if (!placing || (held !== undefined && (await held()))) return placed ?? this.unplaced()\n    const ctx = this.context(command, session, await judged())\n    const [said, route] = await policies.preExecute(ctx, placed !== null)\n    const action =\n      said?.kind === 'ask'\n        ? await this.registry.decisions.resolve(...opQuestion(ctx, said), signal, claimant)\n        : said\n    if (action?.kind === 'abandoned') throw makeAbortError()\n    if (action !== null) return action\n    if (placed !== null) return placed\n    if (route !== null) return this.routed(route)\n    return this.unplaced()\n  }\n\n  /**\n   * Every `preExecute` answer for a line and what they decide, without\n   * running it: what `explain` shows. An Ask reads the ledger's settled\n   * records alone and records nothing. Mirrors Python's\n   * `Router.placement`.\n   */\n  async placement(\n    command: string,\n    session: SessionState,\n    judged: () => Promise<readonly [Walked, Judged[]][]>,\n  ): Promise<[readonly (Deny | Ask | Route)[], RouteDecision<Runtime> | Deny | Pending]> {\n    const policies = this.registry.policies\n    const placing = await policies.wantsFor('preExecute', session.sessionId)\n    if (!placing) return [[], this.unplaced()]\n    const ctx = this.context(command, session, await judged())\n    const answers = await policies.answers('preExecute', ctx)\n    let winner = settled(answers)\n    if (winner?.kind === 'ask') {\n      const standing = await this.registry.decisions.held(...opQuestion(ctx, winner))\n      if (standing !== null) return [answers, standing]\n      winner = agreed(answers.filter((a): a is Route => a.kind === 'route'))\n    }\n    if (winner?.kind === 'deny') return [answers, winner]\n    if (winner?.kind === 'route') return [answers, this.routed(winner)]\n    return [answers, this.unplaced()]\n  }\n\n  /**\n   * The decision a policy's route places a line on (`routed`). Mirrors\n   * Python's `Router._routed`.\n   *\n   * Throws:\n   *   RouteError: no entry or machine has the name.\n   */\n  private routed(route: Route): RouteDecision<Runtime> {\n    this.knownMachine(route.machine)\n    try {\n      return routed(\n        this.runtimes.entries,\n        this.registry.runtimeBindings,\n        route.runtime,\n        route.machine,\n      )\n    } catch (caught) {\n      throw new RouteError(caught instanceof Error ? caught.message : String(caught), {\n        cause: caught,\n      })\n    }\n  }\n\n  /**\n   * Refuse a machine the workspace does not have.\n   *\n   * Throws:\n   *   RouteError: no machine has the name.\n   */\n  private knownMachine(machine: string | undefined): void {\n    if (machine === undefined) return\n    try {\n      this.runtimes.machines.get(machine)\n    } catch (caught) {\n      throw new RouteError(caught instanceof Error ? caught.message : String(caught), {\n        cause: caught,\n      })\n    }\n  }\n\n  /**\n   * The decision for a line no policy placed: each command on its first\n   * capturer, kept for the line's nested evals. Mirrors Python's\n   * `Router._unplaced`.\n   */\n  unplaced(): RouteDecision<Runtime> {\n    return {\n      bindings: Object.assign(\n        Object.create(null) as Record<string, Runtime | null>,\n        this.registry.runtimeBindings,\n      ),\n      fallback: catchAll(this.runtimes.entries),\n    }\n  }\n\n  /**\n   * The runtime entry that serves a command under a decision, as its run\n   * places it, and the machine it runs there on: the `@external` runtime\n   * for a program no name binds (a path runs through the workspace's exec\n   * path first); both empty when the workspace runs it itself. A\n   * `preCommand` route of the command places it over the line's decision,\n   * as its run does. Mirrors Python's `Router.placement_for`.\n   */\n  placementFor(one: Judged, line: RouteDecision<Runtime>): [string, string] {\n    const whole = wholeLineRuntime(line.bindings)\n    if (whole !== null) return [whole.name, machineOf(whole, line)]\n    const route = commandRoute(one.judgment.answers)\n    const placed =\n      route === null\n        ? line\n        : routed(this.runtimes.entries, line.bindings, route.runtime, route.machine ?? line.machine)\n    return this.serving(one, placed)\n  }\n\n  /**\n   * `placementFor` for each of a line's judged commands, one a line runs in\n   * turn (`eval`) under the placement a `preCommand` route gave the command\n   * running it, as its run keeps it. Mirrors Python's `Router.placements`.\n   */\n  placements(\n    judged: readonly Judged[],\n    decision: RouteDecision<Runtime>,\n  ): (one: Judged) => [string, string] {\n    return (one) => {\n      const outer: Judged[] = []\n      for (let at = one.occurrence.parent; at !== null; at = at.parent) {\n        const place = at\n        const held = judged.find((other) => sameOccurrence(other.occurrence, place))\n        if (held !== undefined) outer.push(held)\n      }\n      let line = decision\n      for (const held of outer.reverse()) {\n        const route = commandRoute(held.judgment.answers)\n        if (route !== null) {\n          line = routed(\n            this.runtimes.entries,\n            line.bindings,\n            route.runtime,\n            route.machine ?? line.machine,\n          )\n        }\n      }\n      return this.placementFor(one, line)\n    }\n  }\n\n  /**\n   * Whether a command's `preCommand` route places it off the runtime or\n   * machine its line runs whole on, which that one run cannot honor: a\n   * route that leaves the command where it stands (a runtime that does not\n   * capture it) holds. Throws a `RouteError` for a route that names no\n   * runtime entry. Mirrors Python's `Router.off_line`.\n   */\n  offLine(one: Judged, decision: RouteDecision<Runtime>): boolean {\n    const route = commandRoute(one.judgment.answers)\n    const whole = wholeLineRuntime(decision.bindings)\n    if (route === null || whole === null) return false\n    let placed: RouteDecision<Runtime>\n    try {\n      placed = routed(\n        this.runtimes.entries,\n        decision.bindings,\n        route.runtime,\n        route.machine ?? decision.machine,\n      )\n    } catch (caught) {\n      throw new RouteError(caught instanceof Error ? caught.message : String(caught), {\n        cause: caught,\n      })\n    }\n    const [runtime, machine] = this.serving(one, apart(placed))\n    const [lineRuntime, lineMachine] = this.serving(one, apart(decision))\n    return (\n      wholeLineRuntime(placed.bindings) !== whole ||\n      machineOf(whole, placed) !== machineOf(whole, decision) ||\n      runtime !== lineRuntime ||\n      machine !== lineMachine\n    )\n  }\n\n  /**\n   * The runtime entry and machine that serve a command under a decision\n   * that places each command on its own, as `placementFor` answers them.\n   * Mirrors Python's `Router._serving`.\n   */\n  private serving(one: Judged, placed: RouteDecision<Runtime>): [string, string] {\n    const command = one.judgment.command\n    let decision = placed\n    let fallback = placed.fallback\n    if (one.ctx !== undefined && one.session !== undefined) {\n      if (mirageProgramAt(command, one.ctx.argv, one.session, this.registry, placed) !== null) {\n        return ['', '']\n      }\n      const [consumer, rerouted] = routedConsumer(\n        command,\n        one.ctx.argv,\n        one.session,\n        this.registry,\n        placed,\n      )\n      decision = rerouted ?? placed\n      if (consumer === Consumer.EXTERNAL && !command.includes('/')) {\n        fallback = Object.hasOwn(decision.bindings, EXTERNAL_COMMANDS)\n          ? (decision.bindings[EXTERNAL_COMMANDS] ?? null)\n          : null\n      }\n    }\n    const serving = Object.hasOwn(decision.bindings, command)\n      ? (decision.bindings[command] ?? null)\n      : fallback\n    if (serving === null || serving instanceof WorkspaceRuntime) return ['', '']\n    return [serving.name, machineOf(serving, decision)]\n  }\n\n  /**\n   * The decision that serves a line on one named runtime, its captures over\n   * the static bindings, on one named machine; no runtime leaves each\n   * command on its first capturer.\n   *\n   * Throws:\n   *   RouteError: no entry or machine has the name, or the runtime cannot be selected.\n   */\n  private placed(name: string | undefined, machine: string | undefined): RouteDecision<Runtime> {\n    this.knownMachine(machine)\n    let overlay: Record<string, Runtime>\n    try {\n      overlay = name === undefined ? {} : runtimeBindingsFor(this.runtimes.entries, name)\n    } catch (caught) {\n      throw new RouteError(caught instanceof Error ? caught.message : String(caught), {\n        cause: caught,\n      })\n    }\n    return {\n      bindings: Object.assign(\n        Object.create(null) as Record<string, Runtime>,\n        this.registry.runtimeBindings,\n        overlay,\n      ),\n      fallback: catchAll(this.runtimes.entries),\n      ...(machine !== undefined ? { machine } : {}),\n    }\n  }\n\n  /**\n   * What `preExecute` sees of one line, and `postExecute` before what came\n   * back: the line, every command in it as the gate that runs it will read\n   * it, each with the session it would be judged in, and the session, its\n   * namespace and its files, which a script reads as plain data too.\n   * `judged` is the line pass's reading of the line (`lineJudgments`).\n   */\n  context(\n    command: string,\n    session: SessionState,\n    judged: readonly [Walked, Judged[]][],\n  ): RouteContext {\n    const views = this.registry.policies.views\n    const commands: CommandContext[] = []\n    for (const [item, explained] of judged) {\n      for (const one of explained) {\n        if (one.ctx === undefined) continue\n        const walked = one.session ?? item.session\n        commands.push({ ...one.ctx, ...views?.(walked.sessionId, walked) })\n      }\n    }\n    return {\n      line: command,\n      commands,\n      sessionId: session.sessionId,\n      ...views?.(session.sessionId, session),\n    }\n  }\n}\n"
    },
    {
      "path": "typescript/packages/core/src/workspace/executor/command/command.ts",
      "content": "// ========= Copyright 2026 @ Strukto.AI All Rights Reserved. =========\n// Licensed under the Apache License, Version 2.0 (the \"License\");\n// you may not use this file except in compliance with the License.\n// You may obtain a copy of the License at\n//\n//     http://www.apache.org/licenses/LICENSE-2.0\n//\n// Unless required by applicable law or agreed to in writing, software\n// distributed under the License is distributed on an \"AS IS\" BASIS,\n// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\n// See the License for the specific language governing permissions and\n// limitations under the License.\n// ========= Copyright 2026 @ Strukto.AI All Rights Reserved. =========\n\nimport { shellVoice } from '../../../shell/voice.ts'\nimport { RELAY_COMMANDS } from '../../../commands/builtin/generic/crossmount/constants.ts'\nimport { aggregateFor } from '../../../commands/builtin/generic/crossmount/detect.ts'\nimport {\n  handleCrossMount,\n  isCrossMount,\n  type RunSingle,\n} from '../../../commands/builtin/generic/crossmount/index.ts'\nimport type { OperandMount } from '../../../commands/builtin/generic/crossmount/types.ts'\nimport {\n  prepareProgram,\n  PROGRAM_FILE_COMMANDS,\n  programFiles,\n  valueRefusal,\n} from '../../../commands/builtin/generic/program.ts'\nimport { identityFrom } from '../../../commands/builtin/utils/identity.ts'\nimport type { CLI } from '../../../commands/cli/types.ts'\nimport { invokedEnvNames, suppliedEnvNames } from '../../../commands/cli/walk.ts'\nimport { UsageError } from '../../../commands/errors.ts'\nimport { isBuiltinGrammar, registeredSpec } from '../../../commands/spec/builtins.ts'\nimport { STANDARD_AFTER_SCAN } from '../../../commands/spec/constants.ts'\nimport { spreadOperands } from '../../../commands/spec/flag_view.ts'\nimport { SPECS } from '../../../commands/spec/index.ts'\nimport { standardRequest } from '../../../commands/spec/standard.ts'\nimport type { CommandSpec } from '../../../commands/spec/types.ts'\nimport type { RedirectResult } from '../../../context/session_context.ts'\nimport {\n  currentCaller,\n  getAdmission,\n  sessionAccess,\n  type CallerDispatchFn,\n} from '../../../context/session_context.ts'\nimport { IOResult, materialize, type ByteSource } from '../../../io/types.ts'\nimport type { EntryGate, HandOff } from '../../../policy/types.ts'\nimport { parseFind, type FindExpr } from '../../../rs/find.ts'\nimport { encodeText } from '../../../shell/bytes.ts'\nimport type { CallStack } from '../../../shell/call_stack.ts'\nimport type { JobConsole } from '../../../shell/console/index.ts'\nimport { NOT_FOUND_STATUS } from '../../../shell/constants.ts'\nimport type { JobTable } from '../../../execution/job/index.ts'\nimport type { ParseScope } from '../../../shell/parse/scope.ts'\nimport { Follow, PathSpec } from '../../../types.ts'\nimport { abortable, mergeSignals } from '../../../utils/abort.ts'\nimport { concat } from '../../../utils/bytes.ts'\nimport { compareCodePoints } from '../../../utils/sort.ts'\nimport type { FollowOperands, SessionView, StatPath } from '../../../view/types.ts'\nimport type { EvaluationContext } from '../../evaluation.ts'\nimport { globOptions, resolveGlobs } from '../../expand/globs.ts'\nimport type { ExecuteFn } from '../../expand/types.ts'\nimport { Files } from '../../files.ts'\nimport { EXEC_WRAPPERS } from '../../lookup/constants.ts'\nimport { Consumer, JOB_BUILTINS, lineFacts, lookup, runsAs } from '../../lookup/index.ts'\nimport { MountCommandAmbiguous } from '../../mount/errors.ts'\nimport type { MountEntry } from '../../mount/mount.ts'\nimport type { Namespace } from '../../mount/namespace/namespace.ts'\nimport { pathStat } from '../../mount/namespace/probe.ts'\nimport { MountCommandUnsupported, type MountRegistry } from '../../mount/registry.ts'\nimport { makeCheckUnlink, makeStorageKey } from '../../mount/storage.ts'\nimport type { SessionState } from '../../session/session.ts'\nimport { envSnapshot, sessionView } from '../../session/state.ts'\nimport { ExecutionNode } from '../../types.ts'\nimport { operandFollow } from '../builtins/links/links.ts'\nimport { fanOutTraversal, runWithFanout, shouldFanOut } from '../fanout.ts'\nimport { applyFindActions, openFindFiles, runListedFind } from '../find_action_dispatch.ts'\nimport { resolveNewerRefs } from '../find_refs.ts'\nimport { handleDisown } from '../builtins/disown/disown.ts'\nimport { handleJobs } from '../builtins/jobs/jobs.ts'\nimport { handleKill } from '../builtins/kill/kill.ts'\nimport { handlePs } from '../builtins/ps/ps.ts'\nimport { handleWait } from '../builtins/wait/wait.ts'\nimport {\n  handleCli,\n  handleMountCli,\n  reachesService,\n  walkLeaf,\n  type CLIContext,\n  type LeafCall,\n} from './cli.ts'\nimport { optionError, parseFlags } from './flags.ts'\nimport { runShellFunction } from './functions.ts'\nimport {\n  CWD_DEFAULT_RAW,\n  defaultCwdOperand,\n  mergeScopes,\n  operandPaths,\n  optionLoopExits,\n  pathFlagScopes,\n  routableScopes,\n  routedOperands,\n} from './routing.ts'\nimport { execNode, findStartPoints, nestedShell, runOnMount, type RunOnMountCtx } from './run.ts'\nimport { type ExecuteNodeFn, type ParsedCommand } from './types.ts'\n\n// One handler per JOB_BUILTINS member but ps, which also takes the workspace\n// user; lookup already narrowed the name.\nconst JOB_HANDLERS: Record<\n  string,\n  (\n    jobTable: JobTable,\n    textParts: string[],\n    session: SessionState | null,\n    view: SessionView | null,\n    signal?: AbortSignal,\n    sink?: JobConsole,\n  ) => RedirectResult | Promise<RedirectResult>\n> = {\n  wait: handleWait,\n  kill: handleKill,\n  jobs: handleJobs,\n  disown: handleDisown,\n}\n\n/**\n * Apply find's actions once, at the command boundary. Every runner below\n * this point (one mount, a fan-out over nested mounts, one native run per\n * cross-mount operand) only selects rows and hands them back as\n * `io.records`; the actions run here over all of them together, so\n * a batched `-exec {} +` is one invocation across every start point, as\n * GNU's is, and a per-match action runs in start-point order.\n */\nasync function finishFind(\n  stdout: ByteSource | null,\n  io: IOResult,\n  expr: FindExpr,\n  registry: MountRegistry,\n  context: EvaluationContext,\n  executeFn: ExecuteFn | undefined,\n  vfs: Files,\n  statPath: StatPath,\n  dispatch: CallerDispatchFn,\n  stdin: ByteSource | null,\n  starts: readonly PathSpec[],\n  signal: AbortSignal | undefined,\n): Promise<ByteSource | null> {\n  const session = context.session\n  const [newStdout, actionErr, actionExit] = await applyFindActions(\n    stdout,\n    io,\n    expr,\n    registry,\n    session.cwd,\n    {\n      ...(executeFn !== undefined ? { executeFn } : {}),\n      session,\n      vfs,\n      statPath,\n      dispatch,\n      identity: identityFrom(sessionView(session, context.frame.diagnostics)),\n      stdin,\n      starts,\n      ...(signal !== undefined ? { signal } : {}),\n    },\n  )\n  const warned = expr.warnings.map((line) => encodeText(`${line}\\n`))\n  if (warned.length > 0 || actionErr.length > 0) {\n    const existing = await materialize(io.stderr)\n    io.stderr = concat([...warned, existing, actionErr])\n  }\n  if (io.exitCode === 0) io.exitCode = actionExit\n  return newStdout\n}\n\n/**\n * Each path operand with what the cross-mount decision reads of it: the\n * mount that owns it, the reducer of what `cmdName` resolves to there, and\n * whether a mount sits below it. Mirrors Python's `_operand_mounts`.\n */\nfunction operandMounts(\n  registry: MountRegistry,\n  cmdName: string,\n  scopes: readonly PathSpec[],\n): OperandMount[] {\n  return scopes.map((scope) => {\n    const mount = registry.tryMountFor(scope.virtual)\n    return {\n      path: scope,\n      mount: mount?.prefix ?? null,\n      aggregate: mount?.resolveCommand(cmdName)?.aggregate ?? null,\n      nests: registry.descendantMounts(scope.virtual).length > 0,\n    }\n  })\n}\n\n/** The command's words as the line spelled them, an operand as typed.\n * Mirrors Python's spelled_words. */\nfunction spelledWords(parts: readonly (string | PathSpec)[]): string[] {\n  return parts.map((p) => (p instanceof PathSpec ? p.rawPath : p))\n}\n\n/**\n * Fetch the managed names the tree a mount serves under `name` reads. The\n * line's fill covers installed CLIs only: which mount's tree a head word\n * reaches is known only when the command runs, after any `cd` before it on the\n * line. The names are fetched ahead of the command's admission, as an\n * installed CLI's are, so the gate walks the tree under the values the run\n * reads; an env-filled required option would otherwise stop that walk short\n * of the leaf, and a writing leaf would read as a reader. A name the\n * invocation assigns (`TOKEN=x tok`, `skip`) is the invocation's, so it is\n * never fetched. A failed fetch throws SecretsError. Resolves to whether a\n * value was fetched, which changes how the words read. Mirrors Python's\n * `fill_tree_env`.\n */\nexport async function fillTreeEnv(\n  name: string,\n  args: readonly string[],\n  session: SessionState,\n  registry: MountRegistry,\n  skip: ReadonlySet<string> = new Set(),\n): Promise<boolean> {\n  if (registry.fillEnv === undefined || registry.clis.get(name) !== null) return false\n  const candidates = registry.invocationCandidates(\n    name,\n    [],\n    session.cwd,\n    args,\n    sessionAccess(session),\n  )\n  if (candidates.length !== 1) return false\n  const tree = candidates[0]?.cliFor(name) ?? null\n  if (tree === null || lookup(name, session, registry) !== Consumer.MOUNT) return false\n  const verbs = new Set(args.filter((w) => !w.startsWith('-')))\n  const supplied = suppliedEnvNames(tree.spec, [...args])\n  const names = new Set(\n    [...invokedEnvNames(tree.spec, verbs)].filter((n) => !supplied.has(n) && !skip.has(n)),\n  )\n  // A fill fetches scalars only, so a scalar's text is what it changes.\n  const scalar = (n: string): string | null => {\n    const value = session.vars.get(n)?.value\n    return typeof value === 'string' ? value : null\n  }\n  const before = new Map([...names].map((n) => [n, scalar(n)]))\n  await registry.fillEnv(session, names)\n  return [...names].some((n) => scalar(n) !== before.get(n))\n}\n\n/**\n * The dispatch a command's own ops go through: every op it issues is made by\n * the command, its admission gate included, so a rule scoped to the command\n * reaches the entries below its operands, and a CLI's own reads and every\n * mount run below (one run, a fan-out or a cross-mount) included. Mirrors\n * Python's made_by_command.\n */\nexport function madeByCommand(\n  dispatch: CallerDispatchFn,\n  admission: EntryGate | null,\n): CallerDispatchFn {\n  return (op, path, args, kwargs, report, caller) =>\n    dispatch(op, path, args, kwargs, report, caller ?? { ...currentCaller(), ruleGate: admission })\n}\n\n/** The result of a line that ended before anything ran. Mirrors Python's `_failed`. */\nfunction failed(command: string, exitCode: number, stderr: Uint8Array): RedirectResult {\n  return [\n    null,\n    new IOResult({ exitCode, stderr }),\n    new ExecutionNode({ command, exitCode, stderr }),\n  ]\n}\n\n/**\n * Parse and bind a find line's expression. Resolves to the bound expression,\n * or to the result that ends the line: one find refuses, a -newer reference\n * it cannot stat, a -files0-from run, or a file -fprint cannot create.\n * Mirrors Python's `_bound_find`.\n */\nasync function boundFind(\n  cmdStr: string,\n  parts: readonly (string | PathSpec)[],\n  context: EvaluationContext,\n  registry: MountRegistry,\n  dispatch: CallerDispatchFn,\n  namespace: Namespace | undefined,\n  executeFn: ExecuteFn | undefined,\n  view: SessionView,\n  stdin: ByteSource | null,\n): Promise<FindExpr | RedirectResult> {\n  const session = context.session\n  let findExpr: FindExpr\n  try {\n    const parsedFind = parseFind(spelled