ext.\n  const operands = operandPaths(cmdName, parts.slice(1), session.cwd).filter(\n    (s) => s.walkError !== 'ENOENT',\n  )\n  const ownMount = registry.invocationMount(\n    cmdName,\n    operands,\n    session.cwd,\n    spelledWords(parts).slice(1),\n    sessionAccess(session),\n  )\n  const ownSpec = ownMount?.specFor(cmdName) ?? null\n  const borrowed =\n    SPECS[cmdName] !== undefined && ownSpec !== null && !isBuiltinGrammar(cmdName, ownSpec)\n  if (!borrowed && cmdName in CWD_DEFAULT_RAW) {\n    const operand = defaultCwdOperand(parts, cmdName, registry, session.cwd, stdin)\n    if (operand !== null) {\n      // Where GNU's implied `.` sits: after the pattern for grep/rg\n      // (the first positional is the pattern), right after the command\n      // name for find/tree/du/ls (find's expression tokens must stay\n      // behind the path).\n      parts =\n        cmdName === 'grep' || cmdName === 'rg'\n          ? [...parts, operand]\n          : [head, operand, ...parts.slice(1)]\n    }\n  }\n\n  const pathScopes: PathSpec[] = []\n  for (let i = 1; i < parts.length; i++) {\n    const p = parts[i]\n    if (p instanceof PathSpec) pathScopes.push(p)\n  }\n  const rawArgv = parts.slice(1).map((p) => (typeof p === 'string' ? p : p.virtual))\n\n  // --help and --version answer from the package, never from a backend, so\n  // they are served before mount permission checks and cross-mount routing:\n  // otherwise `rm --version /ro/x` hits the read-only refusal,\n  // `cat --version /ram/a /disk/b` parses against the shared spec, which\n  // carries no injected --version, and fails as an unknown option, and\n  // `mv --help /ram/a /disk/b` reaches the cross-mount relay, which bypasses\n  // the registered wrapper that answers help and MOVED THE FILE instead of\n  // printing the page.\n  const cmdMount = ownMount ?? registry.mountForCommand(cmdName)\n  const cmdSpec = cmdMount?.specFor(cmdName) ?? null\n  const standardOut = standardRequest(cmdName, cmdSpec, rawArgv)\n  if (standardOut !== null) {\n    return standardAnswer(cmdName, cmdStr, cmdSpec, standardOut, parts, session)\n  }\n\n  let prepared: ParsedCommand | null = null\n  if (!borrowed && PROGRAM_FILE_COMMANDS.has(cmdName)) {\n    const programSpec = SPECS[cmdName]\n    if (programSpec !== undefined) {\n      const candidate = parseFlags(\n        parts.slice(1),\n        registeredSpec(cmdName, programSpec),\n        cmdName,\n        session.cwd,\n      )\n      if (programFiles(cmdName, candidate.flagKwargs).length > 0) {\n        prepared = candidate\n        const refusal = optionError(cmdName, prepared)\n        if (refusal !== null) {\n          const [msg, code] = refusal\n          return failed(cmdStr, code, msg)\n        }\n        const [texts, flags, remaining, error] = await prepareProgram(\n          cmdName,\n          prepared.texts,\n          prepared.flagKwargs,\n          stdin,\n          dispatch,\n          prepared.paths,\n        )\n        if (error !== null) {\n          return [\n            null,\n            error,\n            new ExecutionNode({\n              command: cmdStr,\n              exitCode: error.exitCode,\n              stderr: await materialize(error.stderr),\n            }),\n          ]\n        }\n        stdin = remaining\n        prepared = { ...prepared, texts, flagKwargs: flags }\n        pathScopes.splice(0, pathScopes.length, ...prepared.paths)\n      }\n    }\n  }\n\n  const [routingScopes, flagScopes] = borrowed\n    ? [operands, []]\n    : routedScopes(cmdName, cmdMount, rawArgv, parts, pathScopes, prepared, session)\n\n  let findExpr: FindExpr | null = null\n  if (!borrowed && cmdName === 'find') {\n    const found = await boundFind(\n      cmdStr,\n      parts,\n      context,\n      registry,\n      dispatch,\n      namespace,\n      executeFn,\n      view,\n      stdin,\n    )\n    if (Array.isArray(found)) return found\n    findExpr = found\n  }\n\n  // Path-valued flags count: `cp -t /other/mount/dir src` spans mounts\n  // exactly like a positional destination would.\n  if (\n    !borrowed &&\n    isCrossMount(cmdName, operandMounts(registry, cmdName, routingScopes), flagScopes)\n  ) {\n    return runCrossMount(\n      runCtx,\n      cmdName,\n      cmdStr,\n      parts,\n      rawArgv,\n      pathScopes,\n      files,\n      view,\n      cmdMount,\n      prepared,\n      findExpr,\n      stdin,\n    )\n  }\n\n  const spans = spanning(\n    cmdName,\n    cmdStr,\n    registry,\n    routingScopes,\n    borrowed ? ownMount : null,\n    ownSpec,\n    parts,\n    session,\n  )\n  if (spans !== null) return spans\n\n  let mount: MountEntry | null\n  try {\n    mount = await registry.resolveMount(\n      cmdName,\n      routingScopes,\n      session.cwd,\n      rawArgv,\n      sessionAccess(session),\n    )\n  } catch (err) {\n    if (err instanceof MountCommandUnsupported || err instanceof MountCommandAmbiguous) {\n      const errBytes = encodeText(`${err.message}\\n`)\n      return failed(cmdStr, 1, errBytes)\n    }\n    throw err\n  }\n  if (mount === null) {\n    const err = encodeText(`${shellVoice()}${cmdName}: command not found`)\n    return [\n      null,\n      new IOResult({ exitCode: NOT_FOUND_STATUS, stderr: err }),\n      new ExecutionNode({ command: cmdStr, exitCode: NOT_FOUND_STATUS }),\n    ]\n  }\n  const selectedTree = mount.cliFor(cmdName)\n  if (selectedTree !== null) return runTree(mount, selectedTree)\n  return runSingleMount(\n    runCtx,\n    cmdName,\n    cmdStr,\n    parts,\n    rawArgv,\n    mount,\n    files,\n    view,\n    routingScopes,\n    borrowed,\n    prepared,\n    findExpr,\n    stdin,\n  )\n}\n"
