      "path": "python/pyproject.toml",
      "content": "[project]\nname = \"mirage-ai\"\nversion = \"0.0.9a1\"\ndescription = \"A unified virtual filesystem for AI agents. Mount S3, Google Drive, Slack, Gmail, GitHub, Linear, Notion, Postgres, MongoDB, SSH, and more behind one filesystem so agents read, write, and pipe across services with familiar shell commands.\"\nreadme = \"README.md\"\nlicense = \"Apache-2.0\"\nlicense-files = [\"LICENSE\", \"THIRD_PARTY_NOTICES\"]\nrequires-python = \">=3.12\"\nauthors = [\n    { name = \"Zecheng Zhang\", email = \"zecheng@strukto.ai\" },\n]\nkeywords = [\n    \"ai-agents\",\n    \"filesystem\",\n    \"vfs\",\n    \"fuse\",\n    \"s3\",\n    \"google-drive\",\n    \"slack\",\n    \"agent-tools\",\n    \"shell\",\n    \"rag\",\n]\nclassifiers = [\n    \"Development Status :: 3 - Alpha\",\n    \"Intended Audience :: Developers\",\n    \"Operating System :: POSIX :: Linux\",\n    \"Operating System :: MacOS :: MacOS X\",\n    \"Programming Language :: Python :: 3\",\n    \"Programming Language :: Python :: 3.12\",\n    \"Topic :: Software Development :: Libraries :: Python Modules\",\n    \"Topic :: System :: Filesystems\",\n    \"Topic :: Scientific/Engineering :: Artificial Intelligence\",\n]\n\ndependencies = [\n    \"aiofiles>=24.1.0\",\n    \"aiohttp>=3.14.4\",\n    \"fastapi>=0.135.1\",\n    \"httpx>=0.28.1\",\n    \"python-multipart>=0.0.27\",\n    \"orjson>=3.11\",\n    \"pyyaml>=6.0.3\",\n    \"typer>=0.12.0\",\n    \"uvicorn[standard]>=0.41.0\",\n    \"pyjwt[crypto]>=2.14.0\",\n    \"dulwich>=1.2.9\",\n    \"tenacity>=9.1.4\",\n    \"mcp>=2.3.0,<3\",\n    \"jsonschema>=4.26.0\",\n    \"multidict>=6.0\",\n    \"limits>=5.8.0\",\n    \"opentelemetry-api>=1.45.1\",\n]\n\n[project.urls]\nHomepage = \"https://www.strukto.ai/\"\nRepository = \"https://github.com/strukto-ai/mirage\"\nDocumentation = \"https://docs.mirage.strukto.ai\"\nIssues = \"https://github.com/strukto-ai/mirage/issues\"\n\n[project.scripts]\nmirage = \"mirage.cli.main:main\"\nmirage-bash = \"mirage.cli.bash:main\"\n\n[build-system]\nrequires = [\"maturin>=1.9,<2\"]\nbuild-backend = \"maturin\"\n\n# The streams both hosts run are compiled from rust/ into mirage._rs, so a\n# wheel is per platform and carries everything under mirage/ beside it.\n# That includes py.typed, which is PEP 561 consent: without the marker a\n# type checker refuses to read an installed package's annotations and\n# every mirage import resolves to Any, so our own gated-at-zero mypy proves\n# nothing to anyone downstream. It caught the 0.0.5 build_vfs break in one\n# line.\n[tool.maturin]\nmanifest-path = \"../rust/python/Cargo.toml\"\nmodule-name = \"mirage._rs\"\nfeatures = [\"pyo3/extension-module\"]\nexclude = [\"**/__pycache__/**\"]\n\n[project.optional-dependencies]\n# --- python runtime (sandboxed python3 default) ---\n# Pinned exactly: monty's API is still moving fast (0.0.19 replaced the whole\n# execution model, 0.0.20 split the distribution into client + runtime\n# packages), and upstream pins its own worker binary the same way.\nmonty    = [\"pydantic-monty==1.4.0\"]\nwasi     = [\"wasmtime>=46\"]\nquickjs  = [\"wasmtime>=46\"]\n\n# --- storage / object stores ---\ns3       = [\"aioboto3>=15.5.0\", \"botocore>=1.40.61\"]\nr2       = [\"aioboto3>=15.5.0\", \"botocore>=1.40.61\"]\ngcs      = [\"aioboto3>=15.5.0\", \"botocore>=1.40.61\"]\noci      = [\"aioboto3>=15.5.0\", \"botocore>=1.40.61\"]\n\n# --- network / remote ---\nssh      = [\"asyncssh>=2.23.0\"]\nnextcloud = [\"opendal>=0.47.1\"]\n\n# --- huggingface ---\n# hf_buckets is HF's Xet object store and reaches it through OpenDAL. The\n# three Hub repo VFS (hf_models / hf_datasets / hf_spaces) speak the\n# Hub API over aiohttp, which is a core dependency, so they need no extra\n# at all and must not be documented as needing this one.\nhf-buckets = [\"opendal>=0.47.1\"]\n\n# --- mount ---\nfuse     = [\"mfusepy>=1.0.0\"]\n\n# --- mongodb ---\nmongodb  = [\"pymongo>=4.9\"]\n\n# --- gridfs ---\ngridfs   = [\"pymongo>=4.9\"]\n\n# --- postgres ---\npostgres = [\"asyncpg>=0.30.0\"]\n\n# --- redis ---\nredis    = [\"redis[hiredis]>=5.0\"]\n\n# --- mail ---\nemail    = [\"aiosmtplib>=5.1.0\"]\n\n# --- secrets sources ---\ndotenv   = [\"python-dotenv>=1.2.2\"]\naws-sm   = [\"aioboto3>=15.5.0\", \"botocore>=1.40.61\"]\n1password = [\"onepassword-sdk>=0.4.1\"]\n\n# --- data ---\n\n# --- observability ---\nlangfuse = [\"langfuse>=5.0.4\"]\n\n# --- chroma ---\n# thin HTTP-only client; the accessor uses AsyncHttpClient exclusively\nchroma   = [\"chromadb-client>=1.0.0\"]\n\n# --- qdrant ---\nqdrant   = [\"qdrant-client>=1.18.0\"]\n\n# --- openai ---\nopenai      = [\"openai>=3.37.0\", \"openai-agents>=0.24.0\"]\n\n# --- pydantic-ai ---\npydantic-ai = [\n    \"pydantic-ai-slim>=2.61.0\",\n    \"pydantic-ai-backend[console]>=0.2.37\",\n]\n\n# --- deepagents ---\ndeepagents  = [\n    \"deepagents>=0.7.32\",\n]\n\n# --- agno ---\nagno        = [\n    \"agno>=3.1.10\",\n]\n\n# --- claude-agent-sdk ---\nclaude-agent-sdk = [\n    \"claude-agent-sdk>=0.2.174\",\n]\n\n# --- claude-managed-agents ---\nclaude-managed-agents = [\n    \"anthropic>=0.122.0\",\n]\n\n# --- sandboxes ---\ndaytona     = [\n    \"daytona>=0.227.0\",\n]\n\n# --- meta: install everything ---\nall = [\n    \"mirage-ai[s3]\",\n    \"mirage-ai[r2]\",\n    \"mirage-ai[gcs]\",\n    \"mirage-ai[oci]\",\n    \"mirage-ai[ssh]\",\n    \"mirage-ai[nextcloud]\",\n    \"mirage-ai[hf-buckets]\",\n    \"mirage-ai[fuse]\",\n    \"mirage-ai[mongodb]\",\n    \"mirage-ai[gridfs]\",\n    \"mirage-ai[postgres]\",\n    \"mirage-ai[redis]\",\n    \"mirage-ai[email]\",\n    \"mirage-ai[dotenv]\",\n    \"mirage-ai[aws-sm]\",\n    \"mirage-ai[1password]\",\n    \"mirage-ai[langfuse]\",\n    \"mirage-ai[mem0]\",\n    \"mirage-ai[chroma]\",\n    \"mirage-ai[qdrant]\",\n    \"mirage-ai[openai]\",\n    \"mirage-ai[pydantic-ai]\",\n    \"mirage-ai[deepagents]\",\n    \"mirage-ai[agno]\",\n    \"mirage-ai[claude-agent-sdk]\",\n    \"mirage-ai[claude-managed-agents]\",\n    \"mirage-ai[daytona]\",\n    \"mirage-ai[e2b]\",\n]\nsandbox = [\n    \"mirage-ai[s3]\",\n    \"mirage-ai[r2]\",\n    \"mirage-ai[gcs]\",\n    \"mirage-ai[oci]\",\n    \"mirage-ai[ssh]\",\n    \"mirage-ai[nextcloud]\",\n    \"mirage-ai[hf-buckets]\",\n    \"mirage-ai[fuse]\",\n    \"mirage-ai[mongodb]\",\n    \"mirage-ai[gridfs]\",\n    \"mirage-ai[postgres]\",\n    \"mirage-ai[redis]\",\n    \"mirage-ai[email]\",\n    \"mirage-ai[langfuse]\",\n    \"mirage-ai[chroma]\",\n    \"mirage-ai[qdrant]\",\n]\nlancedb = [\n    \"lancedb>=0.33.0\",\n]\nmem0 = [\n    \"mem0ai>=2.0.18\",\n]\ne2b = [\n    \"e2b>=2.62.0\",\n]\n\n[tool.uv]\nconstraint-dependencies = [\"pypdf>=6.19.0\"]\n# uv rebuilds the project only when one of these changes; by default that\n# is pyproject.toml alone, which would leave a Rust edit unbuilt.\ncache-keys = [\n  { file = \"pyproject.toml\" },\n  { file = \"../rust/Cargo.toml\" },\n  { file = \"../rust/Cargo.lock\" },\n  { file = \"../rust/python/Cargo.toml\" },\n  { file = \"../rust/python/src/**/*.rs\" },\n  { file = \"../rust/mirage-rs/Cargo.toml\" },\n  { file = \"../rust/mirage-rs/src/**/*.rs\" },\n  { file = \"../rust/mirage-rs/src/generated/*.dfa\" },\n  { file = \"../rust/vendor/grep-regex/Cargo.toml\" },\n  { file = \"../rust/vendor/grep-regex/src/**/*.rs\" },\n]\n\n[dependency-groups]\ndev = [\n    \"aioresponses>=0.7.6\",\n    \"python-dotenv>=1.2.2\",\n    \"moto[s3,server]>=5.1.22\",\n    \"pre-commit\",\n    \"pytest\",\n    \"pytest-asyncio>=0.24.0\",\n    \"pytest-cov>=7.0.0\",\n    \"pytest-httpx>=0.36.0\",\n    \"pytest-xdist>=3.8.0\",\n    \"mypy>=2.3.0\",\n    \"deadcode>=2.4.1\",\n    \"websockets>=15.0.1\",\n    \"fakeredis[lua]>=2.35.1\",\n    \"google-auth-oauthlib>=1.3.1\",\n    \"tzdata>=2026.5\",\n    \"typesafe-sdk>=0.7.5\",\n    \"opentelemetry-sdk>=1.45.1\",\n]\n\n# Advisory dead-code finder for local use only. NOT a CI gate and not a\n# pre-commit hook: the tool still misreports ~200 live symbols here (see\n# below), so a red run means \"read the diff\", never \"the build is broken\".\n#\n# Run it as:  uv run deadcode mirage/\n#\n# `mirage/` and NOT `tests/` is the load-bearing part of that command. A\n# symbol referenced only by its own test is dead production code, and\n# passing tests/ would count that test as a consumer and hide it. Every\n# symbol removed in the dead-code sweep was found exactly this way.\n#\n# The ignore lists below are false positives, not debt. deadcode resolves\n# names statically, so anything invoked by a framework rather than by name\n# reads as unused, and its four --ignore-*-decorated-with flags are no-ops\n# in 2.4.1, so a decorator cannot be excused as a decorator:\n#   *_cmd            typer verbs registered via @app.command(...)\n#   _validate_*      pydantic @field_validator / @model_validator methods\n#   _normalize_*     (same)\n#   __*__            Protocol __call__, __getattr__ lazy-import shims\n#   runtime/wasm     WASI ABI constant tables, complete on purpose\n#   server/routers   FastAPI handlers registered via @router.get/post\n#   agents/*         adapters implementing third-party framework interfaces\n#   fuse/*           libfuse callbacks dispatched by signature\n[tool.deadcode]\nignore-names = [\n    \"*_cmd\",\n    \"__*__\",\n    \"_validate_*\",\n    \"_normalize_*\",\n    \"_check_*\",\n    \"_coerce_*\",\n    \"_v_*\",\n]\nignore-names-in-files = [\n    \"mirage/runtime/wasm/*\",\n    \"mirage/server/routers/*\",\n    \"mirage/agents/*\",\n    \"mirage/fuse/*\",\n]\n\n[tool.pytest.ini_options]\ntestpaths = [\"tests\"]\naddopts = \"-q --import-mode=importlib\"\nmarkers = [\n    \"network: tests that require network access\",\n    \"runtime_assets: tests requiring the downloaded CPython WASI or QuickJS build\",\n    \"no_host_override: skip the tests/server/conftest autouse MIRAGE_ALLOWED_HOSTS=* override\",\n    \"no_auth_override: skip the tests/server/conftest autouse MIRAGE_AUTH_MODE=local-with-no-token override\",\n]\n\n[tool.mypy]\npython_version = \"3.12\"\n# `files`, not `packages`: the two are mutually exclusive (\"May only\n# specify one of: module/package, files, or command\") and `scripts/` is a\n# directory of top-level modules, not a package. It is listed for the\n# reason typescript/scripts is a pnpm workspace member -- those 13 files\n# generate `spec/` and gate CI (`gen_specs.py` is what the Spec drift\n# step runs), and no typechecker read one of them. The first run found\n# 27 errors in 5 files, among them six capability slots read off a bare\n# `type` in `gen_specs.py`: the same shape `vfs_facts.ts` was fixed\n# for on the typescript side.\nfiles = [\"mirage\", \"../scripts\"]\nignore_missing_imports = true\nwarn_unused_ignores = true\nwarn_redundant_casts = true\ncheck_untyped_defs = true\nno_implicit_optional = true\ndisallow_any_generics = true\n# Every module, rather than an allowlist of 54 against 1826. The\n# allowlist could only ever name what someone remembered to add, so the\n# handles CLAUDE.md prescribes types for (`accessor: Accessor`,\n# `index: IndexCacheStore | None`) went unannotated everywhere it did\n# not reach. TypeScript gets the same guarantee from `strict` in\n# tsconfig.base.json, inherited by every package.\ndisallow_untyped_defs = true\nwarn_return_any = true\n"
    }
